window.DEST=window.DEST||{};window.DEST.a1={"id":"a1","name":"Destination A1","level":"Beginner · Elementary","credit":"Uzbek translations and example sentences by Zoir Akramov (@Zoir_Akramov). Word list from “Destination A1” by Malcolm Mann and Steve Taylore-Knowles.","secs":["Nouns","Verbs & phrasal verbs","Adjectives & adverbs","Phrases","Word formation"],"units":[{"n":3,"t":"My Home","c":[["Address","manzil",0,"My address is 2, Green Road.","Mening manzilim Grin Ro'ud, 2-uy."],["Carpet","gilam",0,"There is a red carpet on my bedroom floor.","Yotoqxonamning polida qizil gilam bor."],["Ceiling","shift, patalok",0,"The ceiling of my room is white.","Mening xonamning shifti oq rangda."],["Curtains","parda",0,"There are green curtains on the windows.","Derazalarda yashil rangli pardalar bor."],["Flat","do'm, kvartira",0,"We live in a flat in Leicester.","Biz Lesterda kvartirada yashaymiz."],["Armchair","kreslo",0,"There is a big armchair in the living room.","Mehmonxonada katta kreslo bor."],["Chair","stul",0,"She was sitting in her favourite chair.","U o'z sevimli stulida o'tirgandi."],["Bed","yotoq, kravat",0,"I'm really tired, so I'm going to bed.","Men juda charchaganman, shuning uchun yotoqqa ketyapman (= uyquga yotyapman)."],["Bookcase","kitob javoni",0,"The books are in the bookcase.","Kitoblar kitob javonida."],["Cupboard","shkaf, javon, idish javoni",0,"It was an old kitchen cupboard.","U eski bir oshxona javoni edi."],["Sofa","divan",0,"Our new sofa is really comfortable.","Bizning yangi divanimiz juda ham qulay."],["Table","stol",0,"We eat at the kitchen table.","Biz oshxona stolida ovqatlanamiz."],["Wardrobe","garderob",0,"Molly puts her clothes in the wardrobe.","Moli kiyimlarini garderobga qo'yadi."],["Garden","bog'",0,"There isn't a garden at this house.","Bu hovlida bog' mavjud emas."],["Ground/First/Second floor","birinchi/ikkinchi/uchinchi qavat (Britaniyada ground floor - birinchi qavatni, first floor - ikkinchi qavatni, second floor - uchinchi qavatni bildiradi)",0,"Our flat is on the second floor.","Bizning kvartiramiz uchinchi qavatda."],["Housework","uy ishlari: supur-sudur, chang artish va hokazo",0,"The children help with the housework.","Bolalar uy ishlariga yordamlashadilar."],["Key","kalit",0,"Is this the key to your flat?","Bu kvartirangizning kalitimi?"],["Bathroom","vannaxona, hammom",0,"Your toothbrush is in the bathroom.","Sizning tish cho'tkangiz hammomda."],["Bedroom","yotoqxona",0,"There are two bedrooms in my house.","Mening uyimda 2 ta yotoqxona bor."],["Kitchen","oshxona",0,"Is there a table in the kitchen?","Oshxonada stol bormi?"],["Living room","mehmonxona (uyning mehmonlar kutiladigan xonasi)",0,"We watch TV in the living room.","Biz mehmonxonada televizor ko'ramiz."],["Wall","devor",0,"There is a photo on the wall.","Devorda surat bor."],["Brush (your teeth)","(tishlarni) tozalamoq, yuvmoq",1,"Do you brush your teeth before you go to bed?","Uyquga yotishingizdan avval tishlaringizni tozalaysizmi?"],["Clean","tozalamoq",1,"My mum cleans the house on Saturdays.","Oyim uyni shanba kunlari tozalaydilar."],["Dust","changini artmoq",1,"My sister and I dust the furniture once a week.","Singlim va men bir haftada bir marta mebellarning changini artamiz."],["Feed (your pet)","(uy jonvorini) ovqatlantirmoq",1,"Do you feed your dog every day?","Kuchugingizni har kuni ovqatlantirasizmi?"],["Get up","o'rnidan turmoq",1,"We get up at 7 am and go to school at 8 am.","Biz tonggi soat 7 da turamiz va 8 da maktabga boramiz."],["Put away","joyiga qo'ymoq",1,"Put your books away now. It's time to go home.","Endi kitoblaringizni joyiga qo'ying. Uyga ketish vaqti bo'ldi."],["Share","baham ko'rmoq, bo'lishmoq, birga foydalanmoq",1,"Do you share a bedroom with your sister?","Yotoqxonadan singlingiz bilan birga foydalanasizmi? (= Singlingiz bilan bir yotoqxonada uxlaysizmi?)"],["Tidy","tozalamoq, yig'ishtirmoq",1,"I tidy my room at the weekend.","Men xonamni dam olish kunida yig'ishtiraman."],["Wash","yuvmoq",1,"We wash our hands in the bathroom.","Qo'llarimizni vannaxonada yuvamiz."],["Water","sug'ormoq",1,"Please water the flowers in the garden.","Iltimos, bog'dagi gullarni sug'orib qo'ying."],["Clean","toza",2,"Do you know where my clean shirt is?","Toza ko'ylagim qayerdaligini bilasizmi?"],["Comfortable","qulay",2,"This is a very comfortable armchair.","Bu juda ham qulay kreslo."],["Daily","har kunlik",2,"My dad has a daily walk before work.","Dadam ish(ga ketish)dan oldin har kunlik piyoda sayrga chiqadi."],["Hard-working","mehnatkash",2,"Sam is hard-working. He always gets high test scores.","Sem mehnatkash. U har doim testlardan yuqori ball oladi."],["Lazy","dangasa, ishyoqmas",2,"Evie is lazy. She doesn't study.","Ivi dangasa. U o'qimaydi."],["Messy","betartib, tartibsiz",2,"Your room is messy. Put your things away in the cupboard.","Xonangiz tartibsiz. Narsalaringizni shkafga o'z joyiga qo'ying."],["Daily","har kuni",2,"We clean the house daily.","Biz uyni har kuni tozalaymiz."],["Downstairs","pastga",2,"I washed my face and went downstairs for breakfast.","Yuzimni yuvdim va nonushta uchun pastga tushdim."],["Upstairs","tepaga",2,"My sister went upstairs to do her homework in her room.","Singlim xonasida uy vazifalarini bajarish uchun tepaga chiqib ketdi."],["Do the cooking/ironing/shopping/vacuuming/washing/washing-up","pishirmoq/dazmollamoq/bozor qilmoq/pliso's qilmoq /kirlarni yuvmoq/idish tovoqlarni yuvmoq",3,"I do the washing in our house and my mum does the ironing.","Bizning uyda men kirlarni yuvaman, oyim esa dazmollaydilar."],["Get dressed","kiyinmoq",3,"I can get dressed in two minutes when I'm late for school.","Maktabga kech qolgan paytimda, 2 daqiqa ichida kiyina olaman."],["Get ready (for school)","(maktabga) tayyorlanmoq",3,"We get up at 7.30 am and get ready for school.","Biz tonggi soat 7.30 da turamiz va maktabga tayyorgarlik ko'ramiz."],["Go home/to bed","uyga bormoq/uyquga yotmoq",3,"We go to bed at about 10 pm.","Biz taxminan tungi soat 10 larda uyquga yotamiz."],["Help someone with","biron kimga biron ishda yordam bermoq",3,"My mum helps me with my homework.","Oyim menga uyga vazifalarim bilan yordamlashadilar."],["Make your bed","to'shagini yig'ishtirmoq, o'rnini yig'ishtirmoq",3,"Tidy up your room. And don't forget to make your bed!","Xonangizni yig'ishtiring. Yotog'ingizni yig'ishtirishni ham unutmang!"],["Make a mess","hamma yoqni to'zitmoq, yoyib tashlamoq",3,"My brother makes a mess in our bedroom and I have to clean it.","Mening ukam yotoqxonamizni yoyib tashlaydi, men esa uni tozalashimga to'g'ri keladi."],["Make a snack","tezgina yegulik tayyorlamoq",3,"When I'm late for work, my wife makes a snack for me.","Ishga kech qolayotgan paytimda, xotinim men uchun tezgina yegulik tayyorlab beradi."],["Tell someone to do something","biron kimga biron narsa qilishni aytmoq, buyurmoq",3,"My teachers told me to do a project.","O'qituvchilarim menga bir loyihani amalga oshirishni aytishdi."],["Agree","fikriga qo'shilmoq",4,"I totally agree with you!","Men sizning fikringizga to'liq qo'shilaman!"],["Disagree","fikriga qo'shilmaslik, kelishmaslik",4,"We sometimes disagree but we never fight.","Biz ba'zan kelisha olmaymiz, lekin hech qachon urushmaymiz."],["Uncomfortable","noqulay",4,"This chair is uncomfortable–can I sit there?","Bu stul noqulay ekan–anavi yerda o'tirsam bo'ladimi?"],["Day","kun",4,"We spent five days in Paris.","Biz Parijda 5 kun o'tkazdik."],["Dirt","kir",4,"The white rug really shows the dirt.","Oq gilamcha rostdan ham kirni ko'rsatadi."],["Dirty","kir, iflos",4,"When my clothes are dirty, I wash them and iron them.","Kiyimlarim kir bo'lganida, men ularni yuvaman va dazmollayman."],["Dust","chang",4,"He brushed the dust off his clothes.","U changni kiyimidan tozalab tashladi."],["Dust","changni artmoq",4,"I always dust the furniture in my room.","Men xonamdagi mebellarning changini doimo artaman."],["Dusty","chang bosgan",4,"The old house was very dusty and dirty.","Eski uy juda chang bosgan va kir edi."],["Laziness","dangasalik",4,"You haven't cleaned your room. I don't like your laziness!","Xonangizni tozalamabsiz. Dangasaligingiz menga yoqmayapti!"],["Lazy","dangasa, ishyoqmas, yalqov",4,"He was not stupid, just lazy.","U tentak emas edi, shunchaki dangasa edi."],["Mess","tartibsizlik",4,"'What a mess!' she said.","'Bu qanday tartibsizlik!' dedi u."],["Messy","tartibsiz, betartib",4,"Your room is always messy. Why don't you clean it?","Sizning xonangiz har doim tartibsiz holatda. Nima uchun tozalamaysiz?"],["Quick","tez",4,"Have you finished already? That was quick!","Allaqachon tugatib bo'ldingizmi? Bu juda tez bo'ldi!"],["Quickly","tezgina, tezlik bilan",4,"Elliot was hungry, so he ate very quickly.","Eliet och edi, shuning uchun u juda tez yedi."]]},{"n":6,"t":"Hobbies And Pastimes","c":[["Birthday party","tug'ilgan kun bazmi",0,"I'm going to my BFF's birthday party next week.","Kelasi hafta men eng yaqin do'stimning tug'ilgan kun bazmiga boraman."],["Fancy dress party","chiroyli va bashang kiyimlar kiyib boriladigan bazm, maskarad",0,"I'm going to a fancy dress party.","Men maskaradga boraman."],["Pyjama party","shunaqangi bazmki, unda siz va boshqa mehmonlar bazmni uyushtirgan do'stingizning uyida tunab qolasiz bir kecha (asosan yoshlar bunday bazm uyushtirishadi)",0,"Our neighbours invited our son to a pyjama party.","Qo'shnilarimiz o'g'limizni bazmga taklif qilishdi."],["Surprise party","bazm sababchisiga aytilmay tashkillashtirilgan bazm, syurpriz qilingan bazm",0,"She's planning a surprise party for her boyfriend.","U yoqtirgan yigiti uchun syurpriz bazm rejalashtiryapti (= yigitiga bazm haqida aytmagan, uni bexabar qoldirgan, syurpriz qilmoqchi)."],["Board game","taxtachada o'ynaladigan o'yin, misol uchun shaxmat, monopoliya, narda",0,"Backgammon is my grandad's favourite board game.","Narda bobomning sevimli stol o'yini."],["Computer game","kompyuter o'yini",0,"My missus doesn't like computer games.","Mening yoqtirgan qizim kompyuter o'yinlarini yoqtirmaydi."],["Video game","video o'yin",0,"We play video games every day.","Biz har kuni video o'yinlar o'ynaymiz."],["Camera","fotokamera",0,"My new camera takes great pictures.","Mening yangi fotokameram zo'r rasmlar oladi."],["Cartoon","multfilm",0,"Megan's watching cartoons on TV now.","Megen hozir televizorda multfilm ko'ryapti."],["Cinema","kinoteatr",0,"Do you like watching films at the cinema or on TV?","Siz filmlarni kinoteatrda ko'rishni yoqtirasizmi yoki televizordami?"],["Disco","diskoteka",0,"I danced a lot at the school disco.","Men maktab diskotekasida rosa raqsga tushdim."],["Film","film, kino",0,"Let's stay in and watch a film.","Keling, uyda qolib film tomosha qilamiz."],["Folk music","milliy musiqa",0,"We sometimes listen to folk music.","Biz ba'zan milliy musiqa tinglab turamiz."],["Pop music","pop musiqa: 1950-yildan beri mashhur bo'lib kelayotgan, kuchli ritmga ammo oddiy ohangga ega bo'lgan musiqa turi",0,"They listen to pop music and watch trash TV all day.","Ular pop musiqasi tinglaydilar va kuni bo'yi bo'lmag'ur televizorni tomosha qiladilar."],["Rap music","rep musiqa: ushbu musiqa turida qo'shiq so'zlari kuylanmaydi, balki tez aytiladi",0,"He's using his rap music to spread the message that violence is wrong.","U zo'ravonlik noto'g'ri ekanligi haqidagi xabarni tarqatish uchun o'zining rep musiqasidan foydalanmoqda."],["Rock music","rok musiqa: elektrik gitara va barabanlarda ijro etiladigan baland shovqinli musiqa turi",0,"He is a big name in the world of rock music.","U rok musiqasi olamida mashhur inson."],["Free time","bo'sh vaqt",0,"What do you do in your free time?","Bo'sh vaqtingizda nima bilan shug'ullanasiz?"],["Hobby","hobbi, sevimli mashg'ulot",0,"My favourite hobby is reading.","Mening sevimli mashg'ulotim kitob o'qish."],["Drums","baraban, nog'ora, do'mbira",0,"Leo plays the drums in his band.","Leo musiqiy guruhida baraban chaladi."],["Guitar","gitara",0,"I want to learn to play the guitar.","Men gitara chalishni o'rganishni istayman."],["Piano","pianino, fortepiona",0,"There's a piano in my house, but I don't know how to play it.","Uyimda pianino bor, ammo uni qanday chalishni bilmayman."],["Trumpet","truba 🎺",0,"Liam is learning to play the trumpet.","Liem truba chalishni o'rganyapti."],["Violin","skripka",0,"I like listening to him play the violin.","Men uning skripka chalishini tinglashni yotiraman."],["Picture","rasm, surat",0,"This picture shows me on my birthday.","Bu surat meni tug'ilgan kunimni ko'rsatadi."],["Song","qo'shiq",0,"I want to play that song again. I like it.","Bu qo'shiqni qayta qo'yishni xohlayman. U menga yoqdi."],["Theatre","teatr",0,"There isn't a theatre in my town–only a cinema.","Mening shahrimda teatr mavjud emas–bor yo'g'i kinoteatr bor."],["TV programme","teledastur",0,"It's my favourite TV programme–I never miss an episode.","U mening sevimli teledasturim–men birontayam episodni o'tkazib yubormayman."],["Draw","chizmoq",1,"Katie is drawing pictures in her sketchpad.","Keti rasm albomida rasmlar chizyapti."],["Enjoy","rohatlanmoq, mazza qilmoq, yoqtirmoq",1,"My sister and I enjoy going to the cinema.","Singlim va men kinoga borishni yoqtiramiz."],["Go out","biror tadbirda qatnashish yoki vaqtni biror joyda o'tkazish uchun uydan chiqmoq",1,"We don't go out when we have school the next day.","Ertasi kuni maktab bo'lganda biz ko'chaga chiqmaymiz (aylangani)."],["Laugh","kulmoq",1,"My sister is laughing at me! She thinks I'm funny!","Opam mening ustimdan kulyaptilar! Ularning o'ylashlaricha men kulguli ekanman!"],["Paint","bo'yamoq / chizmoq",1,"I want to learn to paint pictures.","Men rasm chizishni o'rganishni istayman."],["Relax","dam olmoq, hordiq chiqarmoq",1,"After school, I come home to relax.","Maktabdan so'ng, men dam olish uchun uyga kelaman."],["Spend","(vaqt) sarflamoq, o'tkazmoq",1,"Do you spend a lot of time in your bedroom?","Yotoqxonangizda ko'p vaqt o'tkazasizmi?"],["Sing","kuylamoq",1,"Oscar is singing and playing the guitar now.","Oskar hozir qo'shiq kuylayapti va gitara chalyapti."],["Stay in","uyda qolmoq, biror joyga borishni o'rniga vaqtni uyda o'tkazmoq",1,"I like to stay in and watch TV on Sundays.","Yakshanba kunlari men uyda qolib televizor tomosha qilishni yoqtiraman."],["Watch (TV)","(televizor) tomosha qilmoq",1,"Do you watch TV every day?","Siz har kuni televizor tomosha qilasizmi?"],["Amazing","ajoyib",2,"I love this film. It's amazing!","Bu kino menga juda yoqadi. U ajoyib!"],["Boring","zerikarli",2,"This film is boring. Let's play a game.","Bu kino zerikarli. Keling bir o'yin o'ynaymiz."],["Difficult","qiyin",2,"This test is very difficult. I don't understand it.","Bu test juda qiyin. Uni tushunmayapman."],["Exciting","hayajonli, qiziqarli",2,"This film is very exciting. I'm enjoying it.","Bu film juda qiziqarli. Men undan zavqlanyapman."],["Favourite","sevimli",2,"My favourite programme is on TV now.","Mening sevimli dasturim hozir televizorda ko'rsatilyapti."],["Funny","kulgili, qiziq",2,"This is a very funny cartoon.","Bu juda kulgili multfilm."],["Lovely","ajoyib",2,"It's a lovely day–let's go for a walk.","Bugun ajoyib kun–keling sayrga chiqamiz."],["Really","chindan ham, juda",2,"I think rap music is really great!","Men o'ylashimcha rep juda zo'r!"],["Be good at something/doing something","biror nima qilishda yaxshi bo'lmoq, yaxshi qila olmoq",3,"I enjoy learning Japanese but I'm not good at it.","Men yaponchani o'rganishni yoqtiraman, lekin yaponchada yaxshi emasman."],["Feel bored","zerikkan his qilmoq",3,"I feel bored when I watch a film and it's bad.","Kino ko'rganimda va u yomon bo'lganda, men o'zimni zerikkan his qilaman."],["Go to the cinema/theatre","kinoga/teartga bormoq",3,"Lexi often goes to the cinema to watch films with her friends.","Leksi do'stlari bilan kino ko'rish uchun tez-tez kinoga borib turadi."],["Have fun","ko'ngilchog'lik qilmoq, xursandchilik qilmoq, mazza qilmoq",3,"We usually have fun in our lessons. They aren't boring!","Biz odatda darslarimizda mazza qilamiz. Ular zerikarli emas!"],["Have time to do something","biror narsa qilishga vaqti bo'lmoq",3,"I don't have time to eat breakfast before school.","Maktab oldidan nonushta qilgani vaqtim yo'q."],["Have/Throw a party","bazm uyushtirmoq",3,"We throw a big party every summer. All our friends come to our house.","Biz har yozda katta bazm uyushtiramiz. Barcha do'stlarimiz bizning uyimizga kelishadi."],["Listen to music","musiqa tinglamoq",3,"I listen to music on my phone in my room.","Men xonamda telefonimda musiqa tinglayman."],["Play/Have a game (of)","o'yin o'ynamoq",3,"Let's play a game of basketball!","Keling basketbol o'ynaymiz!"],["Read a book","kitob o'qimoq",3,"I go to bed and read a book at about 10 pm.","Men soat taxminan 10 larda yotoqqa yotaman va kitob o'qiyman."],["Take a picture/photo","suratga olmoq",3,"I haven't taken a photo with my new camera yet.","Men yangi kameram bilan hali rasm olib ko'rganim yo'q."],["Drawing","rasm (qalamda chizilgani, kamerada olingani emas)",4,"I did a drawing in my Art lesson.","Rassomchilik darsida rasm chizdim."],["Enjoy","mazza qilmoq, yoqmoq",4,"Thanks for a great evening. I really enjoyed it.","Ajoyib oqshom uchun tashakkur. Men juda mazza qildim."],["Enjoyable","rohatbaxsh, yoqimli, maroqli",4,"The trip was very enjoyable and I had a great time.","Sayohat juda yoqimli bo'ldi va men vaqtimni ajoyib o'tkazdim."],["Fun","maroq, xursandchilik",4,"We had a lot of fun at Sarah's party.","Saraning bazmida juda mazza qildik (= rosa xursandchilik qildik)."],["Funny","kulgili",4,"You're funny! You always make me laugh!","Siz kulgilisiz! Meni har doim kuldirasiz!"],["Luck","omad",4,"I never had much luck with women.","Ayollar borasida hech qachon omadim chopmagan."],["Lucky","omadli",4,"You were very lucky to find a good smartphone for that price.","Bu narxda yaxshi bir smartfon topganingingiz bu sizning omadingiz."],["Music","musiqa",4,"The music was coming from next door.","Narigi eshikdan musiqa jaranglayotgan edi."],["Musician","musiqachi",4,"He's a great musician–he can play the guitar, violin and piano.","U ajoyib musiqachi–u gitara, skripka hamda pianina chala oladi."],["Musical","musiqani yaxshi tushunadigan",4,"I'm not very musical. I can't play the drums or the piano.","Men musiqani juda ham yaxshi tushunmayman. Men nog'ora yoki pianina chala olmayman."],["Painter","rassom, suratkash",4,"Marc Chagall was a famous Russian painter.","Mark Chagal mashhur rus rassomi bo'lgan."],["Painting","rasm, surat (qalamda chizilgani, kamerada olingani emas)",4,"She didn't want to show the painting until it was finished.","U surat bitguniga qadar, uni ko'rsatishni xohlamadi."],["Paint","rasm chizmoq",4,"My mother paints well.","Oyim yaxshi rasm chizadilar."],["Player","o'yinchi, musiqa asbobi chaluvchisi",4,"Brandon is a great guitar player. I love listening to him.","Brenden ajoyib gitara chaluvchisi. Uni tinglash menga yoqadi."],["Play","o'ynamoq, musiqa asbobi chalmoq",4,"I'm learning to play sax.","Men saksafonni chalishni o'rganyapman."],["Reader","kitobxon, blogni kuzatib boruvchi obunachilar",4,"Does your blog have a lot of readers?","Blogingizda ko'p kuzatib boruvchilar bormi?"],["Reading","o'qish",4,"Reading books is a great hobby.","Kitob o'qish ajoyib mashg'ulot."],["Read","o'qimoq",4,"I didn't have time to read the novel.","Romanni o'qishga vaqtim bo'lmadi."],["Relax","dam olmoq",4,"He was relaxing at home, watching TV.","U televizor tomosha qilib uyda hordiq chiqaryotgandi."],["Relaxing","orombaxsh, hordiq chiqaradigan",4,"We didn't have school today, so we had a relaxing afternoon in the sun.","Bugun maktab yo'q edi, shuning uchun tush vaqtini oftob ostida orombaxsh o'tkazdik."],["Singer","qo'shiqchi",4,"Adele is my favourite singer.","Adel mening sevimli qo'shiqchim."]]},{"n":9,"t":"School Life","c":[["Blackboard/Whiteboard","bo'rda yoziladigan doska/markerda yoziladigan doska",0,"The teacher writes things on the whiteboard.","O'qituvchi narsalarni doskaga yozadi."],["Class","sinf",0,"There are 20 students in our class.","Bizning sinfimizda 20 nafar o'quvchi bor."],["Classroom","sinf xonasi",0,"The pupils are not allowed to use their phones in the classroom.","O'quvchilar sinf xonasida telefondan foydalanishiga ruxsat berilmagan."],["Classmate","sinfdosh",0,"I often laugh with my classmates.","Men tez-tez sinfdoshlarim bilan hazillashib-kulishib turaman."],["Chess/Dancing/Drama/Language/Maths/Science Club","shaxmat/raqs/drama/til/matematika/aniq fanlar to'garagi",0,"We learn things about chess at our Chess Club.","Biz shaxmat to'garagida shaxmat to'g'risidagi narsalarni o'rganamiz. At Dancing Club we learn to do dances. – Raqs to'garagida biz raqs tushishni o'rganamiz. I like Drama Club because we learn about the theatre. – Menga drama to'garagi yoqadi chunki biz teatr haqida o'rganamiz. At Language Club we learn English words and phrases. – Til to'garagida biz inglizcha so'zlar va birikmalarni o'rganamiz. Maths Club teaches us some of the fun things about Maths. – Matematika to'garagi bizga matematika fani to'g'risidagi ba'zi qiziqarli narsalarni o'rgatadi. We're learning about spiders in Science Club this week. – Bu hafta biz aniq fanlar to'garagida o'rgimchaklar haqida o'rganyapmiz."],["Homework","uyga vazifa",0,"Do you get a lot of homework at your school?","Maktabingizda ko'p uy vazifasi olasizmi?"],["Lesson","dars",0,"What time is your Maths lesson today?","Bugungi matematika darsingiz soat nechada?"],["Pupil","(faqatgina) maktab o'quvchi",0,"There are 23 teachers and 450 pupils in my school.","Mening maktabimda 23 nafar o'qituvchi va 450 nafar o'quvchi bor."],["Bag","papka",0,"I carry my books in my school bag.","Men kitoblarimni papkamda olib yuraman."],["Notebook","daftar",0,"I write things in this notebook.","Men narsalarni ushbu daftarga yozib olaman."],["Pencil case","penal",0,"I always have my pencil case with me in the lesson.","Darsda penalim doimo men bilan bo'ladi."],["Pencil sharpener","qalam ochgich",0,"You need a pencil sharpener when your pencil breaks.","Qalamingiz singanida, sizga qalam ochgich kerak bo'ladi."],["Rubber","o'chirg'ich",0,"When I draw, I use a pencil but I never use a rubber.","Qachonki men rasm chizganimda, men qalamdan foydalanaman, lekin men hech qachon o'chirg'ich ishlatmayman."],["Ruler","lineyka, chizg'ich",0,"I have a ruler in my pencil case.","Penalimda chizg'ich bor."],["Art","tasviriy san'at fani (rassomchilik)",0,"I love Art because we draw and paint in our lessons.","Menga tasviriy san'at yoqadi chunki biz darslarimizda chizamiz va bo'yaymiz."],["Geography","geografiya fani",0,"We are learning about Africa in Geography at the moment.","Biz ayni damda geografiya fanida Afrika haqida o'rganyapmiz."],["Handicraft","mehnat darsi",0,"Handicraft is my favourite subject.","Mehnat darsi mening sevimli fanim."],["History","tarix fani",0,"Today we are learning about the 1800s in History.","Bugun biz tarixda darsida 1800-yillar haqida o'rganyapmiz."],["IT (Information Technology)","informatika texnologiyalari fani",0,"I have IT once a week. I use a computer in those lessons.","Menda bir haftada bir marta informatika darsi bor. Men u darslarda kompyuterdan foydalanaman."],["Literature","adabiyot fani",0,"My brother is reading Tolstoy in Literature this week.","Ukam bu hafta adabiyot fanidan Tolstoyni o'qiyapti."],["Maths","matematika fani",0,"I'm not good with numbers, so Maths is hard for me.","Men raqamlar bilan yaxshi emasman, shuning uchun matematika men uchun qiyin."],["Music","musiqa fani",0,"Music is my favourite subject–I love to sing and play the piano.","Musiqa mening sevimli fanim– men qo'shiq kuylash va pianina chalishni yoqtiraman."],["PE (Physical Education)","jismoniy tarbiya fani",0,"In PE we sometimes play basketball.","Jismoniy tarbiya darsida biz ba'zan basketbol o'ynaymiz."],["Science","aniq fanlar jamlanmasi: fizika + kimyo + matematika + biologiya (rivojlangan mamlakatlarda alohida shunday fan mavjud)",0,"I love Science. We learn some interesting things in our lessons.","Men aniq fanlarni yoqtiraman. Darslarimizda bir qancha qiziqarli narsalarni o'rganamiz."],["Term","chorak (maktabda), semestr (universitetda)",0,"There are three terms in the school year.","Maktab o'quv yilida uchta chorak bor."],["Test/Exam","test/imtihon",0,"Our teacher often gives us tests.","O'qituvchimiz bizga tez-tez test berib turadilar."],["Timetable","o'quv jadvali, raspisaniya",0,"According to the timetable, Maths is on Friday.","O'quv jadvaliga ko'ra, matematika juma kuni bo'lar ekan."],["Check","tekshirmoq",1,"I always check that my books are in my bag.","Men doimo kitoblarim papkamda ekanligini tekshiraman (ishonch hosil qilaman)."],["Choose","tanlamoq",1,"What did you choose to wear to the party?","Bazmga qanday kiyim kiyishni tanladingiz?"],["Fail","imtihondan yiqilmoq",1,"Jamie didn't study, so he failed his English test.","Jeymi o'qigani yo'q, shuning uchun u ingliz tili testidan yiqildi."],["Know","bilmoq",1,"Do you know the answer? I don't.","Siz javobni bilasizmi? Men bilmayman."],["Learn","o'rganmoq",1,"Is it hard to learn Russian?","Rus tilini o'rganish qiyinmi?"],["Miss","o'tkazib yubormoq, qoldirmoq, bormaslik",1,"I never miss school. I go there every day.","Men hech qachon maktabni qoldirmayman. Men u yerga har kuni boraman."],["Pass","imtihondan muvaffaqiyatli o'tmoq",1,"I'm really happy because I passed all my exams!","Men juda xursandman chunki hamma imtihonlarimdan o'tdim!"],["Remember","eslamoq, yodida bo'lmoq",1,"Do you remember the name of the film we watched last month?","O'tgan oyda ko'rgan filmimizning nomi yodingizdami?"],["Study","o'qimoq, dars qilmoq",1,"On Sunday evening, I usually study and do my homework.","Yakshanba kunlari kechki payt, odatda men dars qilaman va uyga vazifamni bajaraman."],["Teach","o'qitmoq, dars bermoq",1,"Mr Brown teaches us Maths.","Janob Braun bizga matematikadan dars beradi."],["Boring","zerikarli",2,"I like my school subjects. They're not boring.","Men maktab fanlarimni yoqtiraman. Ular zerikarli emas."],["Correct","to'g'ri",2,"Yes, that is the correct answer. Well done!","Ha, bu to'g'ri javob. Barakalla!"],["Easy","oson",2,"My homework is easy. I usually spend an hour doing it.","Mening uy vazifam oson. Odatda men uni bajarishga bir soat sarflayman."],["Fun","maroqli, qiziqarli",2,"I like our Art lessons. They are fun!","Menga tasviriy san'at darslarimiz yoqadi. Ular juda maroqli!"],["Hard","qiyin",2,"This is a really hard subject. I don't understand it.","Bu juda qiyin fan. Men uni tushunmayman."],["Interesting","qiziqarli",2,"I think Maths is really interesting but Misha thinks it's boring.","O'ylashimcha, matematika fani rosa qiziqarli, lekin Misha uni zerikarli deb o'ylaydi."],["Right","to'g'ri",2,"Is this the right answer?","Bu to'g'ri javobmi?"],["Wrong","xato, noto'g'ri",2,"I'm sorry–that is the wrong answer.","Afsusdaman–lekin bu xato javob."],["Hard","qattiq, tirishib",2,"I want to study hard and get a good grade in my test.","Men tirishib o'qishni va testimda yaxshi baho olishni istayman."],["Be interested in","ga qiziqqan",3,"I'm very interested in music.","Men musiqaga juda qiziqaman."],["Cheat in a test/an exam","testda/imtihonda g'irromlik qilmoq, shpargalkadan foydalanmoq",3,"Students who cheat in an exam will fail.","Imtihonda g'irromlik qiladigan o'quvchilar imtihondan yiqiladilar."],["Do (your) homework","uyga vazifani bajarmoq",3,"I do my homework between 6 pm and 7 pm.","Men uyga vazifamni kechki soat 6 va 7 orasida bajaraman."],["Fail a test/an exam","testdan/imtihondan yiqilmoq",3,"Failing one exam is not the end of the world.","Bittagina imtihondan yiqilish hayot tugadi degani emas."],["Pass a test/an exam","testdan/imtihondan muvaffaqiyatli o'tmoq",3,"I'm really happy when I pass a test at school.","Maktabda testdan muvaffaqiyatli o'tganimda juda xursand bo'laman."],["Find something hard/easy","biror narsani qiyin/oson deb hisoblamoq",3,"I find Geography easy. It's my favourite subject.","Men geografiyani oson deb hisoblayman. U mening sevimli fanim."],["Get a good/bad mark","yaxshi/yomon baho olmoq",3,"When we get a bad mark at school, our teachers call our parents.","Maktabda yomon baho olganimizda, o'qituvchilarimiz ota-onamizga qo'ng'iroq qilishadi."],["Go to school","maktabga bormoq",3,"My sister is only four. She doesn't go to school.","Singlim bor yo'g'i to'rt yoshda. U maktabga bormaydi."],["Have/Take/Do a test/an exam","test/imtihon topshirmoq",3,"Go to bed–you have a test in English tomorrow.","Uyquga yoting–ertaga ingliz tilidan imtihoningiz bor."],["Make a mistake","xato qilmoq",3,"I made a mistake in the test but I passed it.","Testda bitta xato qildim, lekin muvaffaqiyatli o'tdim."],["Pay attention to","ga diqqatini qaratmoq, e'tibor bermoq",3,"Please pay attention to me. What I'm saying is important.","Iltimos, diqqatingizni menga qarating. Aytayotgan gapim muhim."],["Begin","boshlamoq",4,"When does the concert begin?","Konsert qachon boshlanadi?"],["Beginner","biror narsani o'rganishni endigina boshlagan odam",4,"I can't play the violin very well–I'm a beginner.","Skripkani juda yaxshi chala olmayman–men endi boshlovchiman."],["Beginning","boshlanishi",4,"In the beginning, I didn't like my new school.","Boshida, yangi maktabim menga yoqmagandi."],["Choice","tanlov",4,"You have a choice for dinner–vegetables or pasta.","Kechki ovqat uchun tanlov bor–sabzavotlar yoki makaron."],["Incorrect","noto'g'ri",4,"Sorry, but your answer is incorrect. Does anyone know the right answer?","Afsus, lekin javobingiz noto'g'ri. Kimdir to'g'ri javobni biladimi?"],["Educate","ta'lim bermoq",4,"The Ormerod School educates handicapped children.","Ormerod Maktabi imkoniyati cheklangan (aqlan yoki jismonan zaif) bolalarga ta'lim beradi."],["Education","ta'lim",4,"You go to school to get an education. It's important to learn things.","Maktabga ta'lim olish uchun borasiz. Bu narsa o'rganish uchun muhim."],["Knowledge","bilim",4,"I'm amazed by my dad's knowledge. He knows lots of things!","Dadamning bilimi meni lol qodiradi. U juda ko'p narsa biladi!"],["Spell","harflab aytmoq/yozmoq",4,"How do you spell your surname?","Familyangiz qanday yoziladi?"],["Spelling","imlo: so'zlarni to'g'ri yozish san'ati",4,"Spelling is important. You won't get good marks in the test if you spell words wrong.","So'zlarni imloviy jihatdan to'g'ri yozish muhimdir. Agar so'zlarni noto'g'ri harflar bilan yozsangiz, testda yaxshi baho olmaymiz."],["Study","o'qimoq",4,"She studied at New College, Oxford.","U Oksford shahridagi Nyu Kollejida o'qigan."],["Student","o'quvchi: maktab o'quvchisi, universitet o'quvchi, o'quv markazida biror narsa o'rganadigan o'quvchi, istalgan turdagi o'quvchi",4,"Matthew is an Art student. He wants to become a painter.","Masyu rassomchilik fakulteti o'quvchisi. U rassom bo'lishni xohlaydi."],["Teacher","o'qituvchi",4,"Pay attention to what your teachers tell you to do.","O'qituvchilaringiz sizga nima qilishingiz kerakligini aytishayotganiga e'tibor bering."]]},{"n":12,"t":"Making Friends And Getting To Know People","c":[["Adult","voyaga yetgan odam",0,"There were 20 children and 5 adults at the party.","Bazmda 20 nafar bolalar va 5 nafar kattalar bor edi."],["(Best) friend","(eng yaxshi) do'st",0,"My best friend's name is Millie. We get on really well.","Mening eng yaxshi do'stimning ismi Mili. Biz juda yaxshi munosabatdamiz."],["Child/Kid","bola",0,"When I was a child, I loved watching cartoons on TV.","Bolaligimda men televizorda multfilmlar tomosha qilishni yoqtirardim."],["Aunt","xola yoki amma",0,"That's my aunt. She's my mum's sister.","Bu mening xolam. U oyimning opasi/singlisi."],["Brother","aka yoki uka",0,"My brother is 15 and my sister is 12.","Ukam 15 yoshda, singlim esa 12 da."],["Father","ota, dada",0,"My father met my mother in Vladivostok in 1996.","Dadam oyimni 1996-yilda Vladivostokda uchratganlar."],["Grandmother/Grandfather","buvi/bobo",0,"My grandmother sometimes helps me to do my homework.","Buvim ba'zan uy vazifamni bajarishimga yordam beradilar."],["Mother","ona, oyi",0,"My mother works as a dentist.","Oyim tish shifokori bo'lib ishlaydilar."],["Nephew","o'g'il bola jiyan",0,"That's my nephew. He's my brother's son.","Bu mening jiyanim. U akamning o'g'li."],["Niece","qiz bola jiyan",0,"That's my niece. She's my brother's daughter.","Bu mening jiyanim. U akamning qizi."],["Sister","opa yoki singil",0,"I am from a big family. I have two brothers and three sisters.","Men katta oiladan chiqqanman. Mening ikkita aka-ukam va uchta opa-singillarim bor."],["Uncle","tog'a yoki amaki",0,"That's my uncle. He's my mum's brother.","Bu mening tog'am. U oyimning ukasi/akasi."],["Guy","bola",0,"I like my brother. He's a good guy.","Akam menga yoqadi. U yaxshi bola."],["Guys","bolalar",0,"How are you doing, guys?","Ishlaringiz qanday, bolalar? (= Yaxshimisizlar, bolalar?)"],["Neighbour","qo'shni",0,"My neighbour lives on the first floor and I live on the second.","Qo'shnim 1-qavatda yashaydi, men esa 2-qavatda."],["Relative/Relation","qarindosh",0,"Sometimes we have a big party and invite all our relatives.","Biz ba'zida katta bazm uyushtiramiz va barcha qarindoshlarimizni taklif qilamiz."],["Teenager","o'smir, 13-19 yoshlardagi odam",0,"I'm 13 today–I'm a teenager now!","Men bugun 13 yoshga to'ldim–endi men o'smir yigitman/qizman!"],["Become","(kelajakda) bo'lmoq",1,"My aunt is studying to become a doctor.","Xolam shifokor bo'lish uchun o'qiyaptilar."],["Chat","suhbatlashmoq, gaplashmoq, gurunglashmoq",1,"I like chatting to people on the computer.","Men kompyuterda odamlar bilan gaplashishni yoqtiraman."],["Fall out with someone","janjallashib-tortishib qolmoq, xafalashib qolmoq",1,"Phoebe said some really bad things to me and I fell out with her.","Fibi menga yomon gaplar aytdi va men u bilan janjallashib qoldim."],["Get on (well) with someone","biror kim bilan yaxshi chiqishmoq, yaxshi munosabatda bo'lmoq",1,"I get on with all my classmates. We're a great class!","Men barcha sinfdoshIarim bilan yaxshi chiqishaman. Biz ajoyib sinfmiz!"],["Hang out with someone","biror kim bilan vaqt o'tkazmoq",1,"I usually hang out with my friends at the weekend.","Men odatda hafta oxirini do'stlarim bilan o'tkazaman."],["Happen","sodir bo'lmoq, ro'y bermoq",1,"Hi, Ethan. What happened at school today?","Salom, Isen. Bugun maktabda nima bo'ldi?"],["Invite","taklif qilmoq",1,"My best friend invited me to her pyjama party this weekend.","Eng yaxshi do'stim meni hafta oxiridagi kechaga taklif qildi."],["Look","ko'rinmoq",1,"You look happy. Did you pass your test?","Xursand ko'rinasiz. Testdan muvaffaqiyatli o'tdingizmi?"],["Meet","uchrashmoq",1,"Let's meet outside the cinema at 7 pm.","Keling kechki soat 7 da kinoteatr tashqarisida uchrashamiz."],["Move","ko'chmoq; harakatlanmoq",1,"I don't want to move to a new school. I'm happy here.","Men yangi maktabga o'tishni istamayman. Men shu yerda xursandman."],["Share","baham ko'rmoq, bo'lishmoq, ulashmoq",1,"Do you want to share a pizza with me?","Men bilan birga pitsa yeyishni xohlaysizmi?"],["Sound","quloqqa yaxshi/ajoyib bo'lib jaranglamoq, eshitilishidan yaxshi g'oyaga o'xshamoq",1,"A fancy dress party sounds like a great idea!","Maskarad ajoyib g'oyaga o'xshaydi!"],["Cool","ajoyib, zo'r, urfdagi",2,"My parents gave me a cool new phone!","Ota-onam menga zo'r yap-yangi telefon berishdi!"],["Different","turli, boshqacha, har xil",2,"Do you like learning different things in Science class?","Aniq fanlar darsida har xil narsalarni o'rganish yoqadimi sizga?"],["Elder","yosh jihatdan kattaroq (qarindoshlarga nisbatan qo'llaniladi)",2,"I'm 12. Jacob's my elder brother–he's 17.","Men 12 yoshdaman. Jeykeb mening akam–u 17 yoshda."],["Little","yosh jihatdan kichikroq (qarindoshlarga nisbatan qo'llaniladi)",2,"I was playing with my little sister last night–she's only two.","Men o'tgan tunda singlim bilan o'ynayotgan edim–u bor yo'g'i ikki yoshda."],["Friendly","do'stona, muloyim",2,"Our teachers are very friendly–they make the lessons nice.","O'qituvchilarimiz juda do'stona–ular darsni ajoyib qilishadi."],["Kind","mehribon, yaxshi",2,"My best friend is kind and friendly.","Mening eng yaxshi do'stim mehribon va do'stona."],["Same","bir xil",2,"Amelie and I get on well because we like the same music.","Emili va men yaxshi chiqishamiz chunki biz bir xil musiqani yoqtiramiz."],["Special","maxsus, o'zgacha",2,"Today is a special day. It's my birthday!","Bugun o'zgacha kun. Mening tug'ilgan kunim!"],["Be born in","da tug'ilgan",3,"I was born in Tomsk in 2004.","Men 2004-yilda Tomsk shahrida tug'ilganman."],["Have a chat with someone","biror kim bilan suhbatlashmoq",3,"I had a chat with Jasmine yesterday. She told me to say hello to you.","Men kecha Jazmin bilan suhbatlashgandim. Sizga salom aytib qo'yishimni aytdi."],["Chat online","internetda suhbatlashmoq",3,"Last night I was chatting online with my uncle in the USA.","O'tgan tunda men AQShdagi tog'am bilan internetda suhbatlashyotgandim."],["Have a good/nice time","vaqtni yaxshi/ajoyib o'tkazmoq",3,"Have a nice time at the party tomorrow!","Ertangi kechada vaqtni ajoyib o'tkazing!"],["Have something in common","o'xshash jihatlari, xarakterlari bo'lmoq",3,"My brother and I have something in common–we both love rock music.","Akam va mening bir o'xshashligimiz bor–biz ikkimiz ham rok musiqa turini yoqtiramiz."],["Look like someone","ko'rinishi jihatdan biror kimga o'xshamoq",3,"A lot of people say I look like my mum but I think I look like my dad.","Ko'plab odamlar men oyimga o'xshashimni aytadi, lekin menimcha men dadamga o'xshayman."],["Make friends","do'st orttirmoq",3,"I moved to a new school but I soon made friends there.","Men yangi maktabga o'tdim, lekin tez orada u yerda do'stlar orttirib oldim."],["Say sorry","afsusda ekanligini aytmoq, uzr so'ramoq",3,"When I do something bad, I always say sorry.","Qachonki men biror yomon ish qilganimda, men uzr so'rayman."],["Talk to someone","biror kim bilan gaplashmoq",3,"I talked to the new girl at school today. She's nice!","Men bugun maktabdagi yangi qiz bilan gaplashdim. U ajoyib!"],["Argue","bahslashmoq, tortishmoq",4,"I don't want to argue with you—just do it!","Men siz bilan tortishishni istamayman–shunchaki bajaring uni!"],["Argument","bahs, tortishuv",4,"I had an argument with Anna but we're friends again now.","Anna bilan o'rtamizda tortishuv bo'lgandi, lekin hozir yana do'stlarmiz."],["Beauty","go'zallik, chiroy",4,"The beauty of the city amazed her.","Shaharning go'zalligi uni lol qoldirdi."],["Beautiful","go'zal, chiroyli",4,"This painting is beautiful. Did you paint it?","By rasm chiroyli ekan. Uni siz chizganmisiz?"],["Child","yosh bola",4,"You're behaving like a child.","O'zingizni xuddi yosh boladay tutyapsiz."],["Childhood","bolalik davri",4,"Did you have a happy childhood?","Bolalik davringiz baxtli o'tganmi?"],["Differ","farq qilmoq, boshqacha bo'lmoq",4,"The models differ in size and shape.","Maketlar o'lcham va shakl jihatdan farq qiladi."],["Different","farqli, boshqacha",4,"Our old teacher left. We have a different teacher now.","Bizning oldingi ustozimiz ketdi. Hozir bizning ustozimiz boshqa."],["Friend","do'st",4,"We met at school and became lifelong friends.","Biz maktabda uchrashib qolganmiz va bir umrlik do'stlarga aylanganmiz."],["Friendship","do'stlik (rishtasi)",4,"My friendship with Lydia is very important to me.","Lidia bilan do'stligimiz menga juda muhim."],["Friendly","do'stona, xushmuomala",4,"If you are friendly to dogs, they won't hurt you.","Agar siz kuchuklarga xushmuomala bo'lsangiz, ular sizga ozor yetkazmaydi."],["Unfriendly","do'stona bo'lmagan, qo'pol",4,"Lola was very unfriendly. She told me to leave!","Lola juda qo'pol bo'ldi. U mendan ketishimni so'radi!"],["Happy","xursand",4,"I'm very happy for you.","Siz uchun juda xursandman."],["Unhappy","xafa",4,"Why are you frowning? Are you unhappy?","Nega xo'mrayyapsiz? Xafamisiz?"],["Help","yordam bermoq",4,"He always helps with the housework.","U har doim uy ishlarida yordam beradi."],["Help","yordam",4,"Thank you for all your help.","Barcha yordamingiz uchun rahmat."],["Helpful","yordami tegadigan, yordamga tayyor, foydali",4,"Thanks for cleaning the house. You've been very helpful.","Uyni tozalaganingiz uchun rahmat. Katta yordamingiz tegdi."],["Invitation","taklifnoma",4,"I have an invitation to go to Libby's party.","Libining kechasiga borish uchun taklifnomam bor."],["Unkind","bemehr, qo'pol",4,"You were unkind to your aunt. You have to apologise.","Xolangizga qo'pol munosabatda bo'ldingiz. Kechirim so'rashingiz kerak."],["Kindness","mehribonchilik, mehr",4,"She bought me some flowers to thank me for my kindness.","U mehribonchiligim uchun menga tashakkur bildirish maqsadida menga gullar sotib olib berdi."],["Meeting","uchrashuv; majlis",4,"My mum has a meeting with my teachers at the school tomorrow.","Ertaga maktabda oyimning o'qituvchilarim bilan uchrashuvlari bor."]]},{"n":15,"t":"Travel","c":[["Airport","aeroport",0,"We're going to the airport to meet my uncle.","Tog'amni kutib olish uchun aeroportga ketyapmiz."],["Beijing","Pekin",0,"Beijing is the capital of China.","Pekin Xitoy davlatining poytaxti."],["Berlin","Berlin",0,"Berlin is the capital of Germany.","Berlin Germaniya davlatining poytaxti."],["London","London",0,"London is a very famous city.","London juda mashhur shahar."],["Madrid","Madrid",0,"Madrid is the capital of Spain.","Madrid Ispaniya davlatining poytaxti."],["Moscow","Moskva",0,"My uncle and aunt live in Moscow.","Mening tog'am va ammam Moskvada yashaydilar."],["Paris","Parij",0,"People say Paris is a very attractive city at night.","Odamlar aytishicha Parij tunda maftunkor shahar bo'lar ekan."],["Rome","Rim",0,"Rome is the capital of Italy.","Rim Italiya davlatining poytaxti."],["Tokyo","Tokyo",0,"Tokyo is the capital of Japan.","Tokyo Yaponiya davlatining poytaxti."],["Washington","Vashington",0,"Washington is the capital of the USA.","Vashington AQSh davlatining poytaxti."],["Hotel","mehmonxona",0,"Did you stay in a hotel in Amsterdam?","Amsterdam shahrida mehmonxonada turdingizmi?"],["Journey","sayohat, safar",0,"Did you have a comfortable journey?","Safaringiz qulay bo'ldimi (= noqulaylik tug'ilmadimi)?"],["Passport","pasport, shaxsni tasdiqlovchi guvohnoma",0,"Show your passport at the hotel when you check in.","Mehmonxonada ro'yxatdan o'tayotganingizda, pasportingizni ko'rsating."],["Plane","samalyot",0,"My plane leaves at 6.45 am and arrives at 9 am.","Samalyotim tonggi 6.45 da yo'lga chiqadi va 9.00 da yetib boradi."],["Ticket","chipta, bilet",0,"I've just bought my ticket for the train.","Men hozirgina poyezd uchun chipta sotib oldim."],["Tour","sayohat, ekskursiya",0,"We went on a tour of Athens.","Biz Asens shahri bo'ylab ekskursiyaga chiqdik."],["Tourist","turist, sayyoh",0,"Do tourists come here in the summer?","Yozda bu yerga sayyohlar keladimi?"],["Town","kichik shahar: 10,000-100,000 aholiga ega",0,"What is the name of the town where you live?","Siz yashaydigan shaharning nomi nima?"],["City","kattaroq shahar: 1 milliondan kam bo'lgan aholiga ega",0,"Rome is one of the great cities of the world.","Rim dunyoning ulug'vor shaharlaridan biri."],["Train station","poyezd stansiyasi",0,"Meet me at the train station at 3 pm.","Soat 3 da meni poyezd stansiyasida kutib oling."],["Arrive in/at","ga yetib bormoq (arrive in - katta joylar, masalan shaharlar va davlatlarga nisbatan qo'llaniladi; arrive at - yopiq binolarga, masalan aeroport va poyezd stansiyalariga nisbatan qo'llaniladi)",1,"We leave here at 1 pm and arrive in London at 3 pm.","Biz bu yerdan soat 1 da jo'naymiz va Londonga soat 3 da yetib boramiz. The train arrived at the station 20 minutes late. – Poyezd stansiyaga 20 daqiqa kechikib yetib keldi."],["Check in/out","mehmonxonaga ro'yxatdan o'tmoq va xona olmoq/mehmonxona ro'yxatidan chiqmoq",1,"We checked in at the hotel and went for a walk around the city.","Biz mehmonxonada ro'yxatdan o'tdik va shahar bo'ylab sayrga chiqdik. I'm sorry, they aren't here. They checked out this morning. – Kechirasiz, ammo ular bu yerda emas. Ular bugun tongda mehmonxonadan ketishdi."],["Enjoy","rohatlanmoq, lazzat olmoq, yoqtirmoq",1,"I don't enjoy travelling on a plane but I love trains.","Men samalyotda sayohat qilishni yoqtirmayman, lekin poyezdlar menga yoqadi."],["Fly","uchmoq",1,"It takes four hours to fly to Paris from here.","Bu yerdan Parijga uchish uchun 4 soat ketadi."],["Get in/out of","mashinaga o'tirmoq/mashinadan tushmoq",1,"Get in the car and belt up.","Mashinaga o'tiring va kamarni mahkamlang. We got out of the car and went in the house. –Biz mashinadan tushdik va uyga kirib ketdik."],["Get on/off","(avtobus, samalyot, poyezd)ga chiqmoq/dan tushmoq",1,"I didn't want to get on the wrong bus.","Men noto'g'ri avtobusga chiqib qolishni xohlamagandim. I got off the train at the wrong station. – Men noto'g'ri stansiyada poyezddan tushib qoldim."],["Leave","jo'namoq, yo'lga chiqmoq, tark etmoq",1,"We leave at 6 am and we arrive at 5 pm.","Biz tonggi soat 6 da yo'lga chiqamiz va kechki soat 5 da yetib boramiz."],["Stay","bir necha kun yashamoq, turmoq, tunamoq",1,"Where are you going to stay in Madrid?","Madridda qayerda turmoqchisiz (= mehmonxonadami yoki do'stingiznikidami...)?"],["Travel","sayohat qilmoq",1,"I've never travelled to a foreign country.","Men hech qachon xorijiy mamlakatga sayohat qilmaganman."],["Visit","tashrif buyurmoq, biror kimni ko'rish uchun bormoq",1,"We're going to Rome to visit my uncle.","Biz amakimni ko'rish uchun Rimga ketyapmiz."],["Attractive","maftunkor, jozibador",2,"That's an attractive building. It's really beautiful.","Bu maftunkor bino ekan. Juda chiroyli."],["Crowded","aholi ko'p bo'lgan, gavjum",2,"The city is very crowded. There are lots of people living here.","Shahar juda gavjum. Bu yerda yashaydigan juda ko'p odam bor."],["Excited","quvongan, zavqlangan",2,"I'm excited about going to India. I've never been there before.","Hindistonga borishdan quvonib ketyapman. Men avval hech qachon u yerda bo'lmaganman."],["Exciting","quvonarli, ajoyib",2,"It is very exciting to arrive in Venice at night.","Venetsiyaga tunda borish juda ajoyib."],["Famous","mashhur",2,"Have you ever met a famous singer or a film star?","Hayotingiz davomida hech bir mashhur qo'shiqchi yoki kino yulduzini uchratganmisiz?"],["Foreign","xorijiy, chet (el)",2,"Have you ever been to a foreign country?","Hayotingiz davomida hech bir xorijiy mamlakatda bo'lganmisiz?"],["Modern","zamonaviy",2,"Our house is not old. It's very modern.","Bizning uyimiz eski emas. U juda zamonaviy."],["Popular","ko'plab odamlarga tanish, taniqli",2,"This place is very popular with tourists.","Bu joy sayyohlar orasida taniqli. (= Ko'p sayyohlar tashrif buyuradi.)"],["Safe","xavfsiz",2,"Is it safe to walk around the town at night?","Shahar bo'ylab tunda aylanib yurish xavsizmi?"],["By bus/car/plane/taxi/train","avtobus/mashina/samalyot/taksi/poyezd orqali",3,"We always go to school by bus.","Biz maktabga doimo avtobusda boramiz."],["Go on a bus/a walking tour","avtobusda/piyoda sayrga chiqmoq, biror joyni aylanmoq",3,"I went on a bus tour of the city–it was great!","Men shahar bo'ylab avtobusda aylandim–ajoyib bo'ldi! This summer we went on a walking tour around Provence. – Bu yozda biz Provens bo'ylab piyoda aylandik."],["Have a good time","vaqtni yaxshi o'tkazmoq, mazza qilmoq",3,"We had a good time in Spain.","Ispaniyada vaqtni yaxshi o'tkazdik."],["Have a problem","muammoga uchramoq",3,"When I have a problem, I talk to my parents. That usually helps.","Qachonki muammoga uchrasam, ota-onamga aytaman. Bu odatda yordam beradi."],["On a trip to","biror yerga sayohatda, ketayabdi",3,"My parents are on a trip to Madrid.","Ota-onam Madridga ketayaptilar (= yo'ldalar, safardalar)."],["On holiday","ta'tilda",3,"I'm on holiday in Italy. I love it here!","Men Italiyada ta'tildaman. Menga bu yer juda yoqdi!"],["See the sights","diqqatga sazovor joylarni aylanmoq",3,"When I visit a new city, I always want to see the sights.","Qachonki yangi bir shaharga tashrif buyurganimda, men har doim diqqatga sazovor joylarini ko'rishni xohlayman."],["Take a picture/photo of","ni rasmga olmoq",3,"I'll take a photo of you.","Sizni rasmga olib qo'yaman."],["America","Amerika",4,"We moved to America when I was eight.","8 yoshlik paytimda biz Amerikaga ko'chib o'tdik."],["American","Amerikalik, Amerikaga tegishli",4,"American English has different spelling to British English.","Amerika ingliz tilisi Britaniya ingliz tilisiga qaraganda boshqacha imloga ega (= ba'zi so'zlar yozilishi jihatdan farq qiladi)."],["Australia","Avstraliya",4,"They went to Australia to start a new life.","Ular yangi hayot boshlash uchun Avstraliyaga borishdi."],["Australian","Avstraliyalik, Avstraliyaga tegishli",4,"The kangaroo and koala are typical Australian animals.","Kenguru va koala Avstraliyaga xos hayvonlar."],["Britain","Britaniya",4,"Britain does not have a written constitution.","Britaniya yozma holatdagi konstitutsiyaga ega emas."],["British","Britaniyalik, Britaniyaga tegishli",4,"The American word \"color\" is spelled \"colour\" in British English.","\"Color\" amerikancha so'zi britanchada \"colour\" shaklida yoziladi."],["China","Xitoy",4,"She has gone to China.","U Xitoyga ketgan (= u hozir Xitoyda)."],["Chinese","Xitoylik, Xitoyga tegishli",4,"Have you ever eaten Chinese food?","Hayotingiz davomida hech xitoy taomi yeb ko'rganmisiz?"],["France","Fransiya",4,"'How are you going to France?' 'We're going by boat.'","'Fransiyaga qanday qilib ketyapsizlar?' 'Biz qayiqda ketyapmiz.'"],["French","Fransuz, Fransiyaga tegishli",4,"Jean-Pierre is a student at my school. He's French and he was born in Paris.","Jin Piyer mening maktabimda o'quvchi. U fransuz va u Parijda tug'ilgan."],["Germany","Germaniya",4,"Last month I went on a school trip to Germany.","O'tgan oyda men maktab safarida Germaniyaga bordim."],["German","Germaniyalik, Germaniyaga tegishli",4,"Hans is from Germany and he's looking for a shop where they sell German food.","Hens Germaniyadan va u germaniya taomlari sotiladigan do'kon izlayapti."],["Japan","Yaponiya",4,"We went to Japan last April.","Biz o'tgan aprel oyida Yaponiyaga bordik."],["Japanese","Yapon, Yaponiyaga tegishli",4,"We went to Tokyo and had Japanese food. It was very good.","Biz Tokyoga bordik va yapon taomi yedik. Juda yaxshi ekan u."],["Russia","Rossiya",4,"He worked as a British spy in Russia.","U Rossiyada ingliz josusi bo'lib ishlagan."],["Russian","Rossiyalik, Rossiyaga tegishli",4,"What is your favourite Russian food?","Sizning sevimli rus taomingiz nima?"],["Spain","Ispaniya",4,"I've never been to Spain.","Men hech qachon Ispaniyada bo'lmaganman."],["Spanish","Ispaniyalik, Ispaniyaga tegishli",4,"Real Madrid and Barcelona are Spanish football teams.","Real Madrid va Barselona ispan futbol jamoalari."]]},{"n":18,"t":"Sports And Healthy Lifestyle","c":[["Athlete","sportchi",0,"William loves running. He's going to become an athlete.","Vilyem yugurishni yoqtiradi. U sportchi bo'lmoqchi."],["Athletics","yengil atletika",0,"I love watching all kinds of sport and athletics on TV.","Men televizorda sport va atletikaning barcha turini tomosha qilishni yoqtiraman."],["Exercise","mashq",0,"Do you do a lot of exercise in PE?","Jismoniy tarbiya darsida juda ko'p mashq qilasizmi?"],["Football/Basketball match","futbol/basketbol o'yini, musobaqasi, sport uchrashuvi",0,"Have you ever been to a football match?","Hayotingiz davomida hech bir futbol musobaqasiga borganmisiz? (= Stadionda tomosha qilganmisiz?)"],["Football/Basketball player","futbolchi/basketbolchi",0,"My friend wants to become a basketball player.","Mening do'stim basketbolchi bo'lishni istaydi."],["Game of football/basketball","futbol/basketbol o'yini",0,"Let's play a game of football!","Keling futbol o'ynaymiz!"],["Goal","go'l, natija",0,"We played a game of football and I scored two goals.","Biz futbol o'ynadik va men ikkita go'l qayd etdim."],["Gym","sport zali",0,"Sometimes I go to the gym to exercise.","Ba'zan men mashq qilish uchun sport zaliga boraman."],["Healthy/Junk food","sog'liqqa foydali ovqat/tez tayyor bo'ladigan fast food",0,"I try to eat healthy food.","Men sog'liqqa foydali ovqat yeyishga harakat qilaman."],["Race","poyga",0,"My favourite athletics event is the 100-metre race.","Mening sevimli yengil atletika sportim bu 100 metrga yugurish poygasi."],["Stadium","stadion",0,"People are walking to the stadium to watch the big match.","Odamlar ushbu katta o'yinni ko'rish uchun stadionga piyoda kelishyapti."],["Team","jamoa",0,"My favourite football team lost the match today.","Mening sevimli futbol jamoam bugun o'yinni boy berdi."],["Cycle","velosipedda uchmoq",1,"My dad wants to be fit, so he cycles to work in the morning.","Dadam jismonan tetik bo'lishni istaydi, shuning uchun u tongda ishga velosipedda boradi."],["Exercise","mashq qilmoq",1,"It's important to exercise daily. Walking is a great way to do that.","Har kuni mashq qilish muhim. Piyoda sayr qilish bunday qilishning ajoyib yo'li."],["Lose","yutqazmoq, mag'lub bo'lmoq, boy bermoq",1,"I want to score a goal–I don't want to lose this match!","Men go'l urishni istayman–bu o'yinni boy berishni istamayman!"],["Roller-skate","to'rt g'ildirakli konkida uchmoq",1,"How did you learn to roller-skate? I always fall!","To'rt g'ildirakli konkida uchishni qanday o'rgangansiz? Men doim yiqilib tushaman!"],["Skate","konkida uchmoq",1,"I learned to skate on ice in Canada.","Men muz ustida konkida uchishni Kanadada o'rganganman."],["Skateboard/Snowboard","skeytbordda/snovbordda uchmoq",1,"When you know how to skateboard, it's easy to snowboard.","Siz qanday qilib skeytbordda uchishni bilsangiz, snovbordda uchish oson."],["Ski","chang'ida uchmoq",1,"We learned to ski in the mountains of Austria.","Biz chang'i uchishni Avstriya tog'larida o'rganganmiz."],["Swim","suzmoq",1,"I love to swim in the sea in the summer.","Men yozda dengizda suzishni yoqtiraman."],["Take up","biror sport bilan shug'ullanishni boshlamoq",1,"I think I'm going to take up a new sport.","Menimcha men yangi bir sport bilan shug'ullanishni boshlamoqchiman."],["Win","yutmoq, g'alaba qozonmoq, g'olib bo'lmoq",1,"It's very exciting when you win a race.","Poygada g'olib bo'lish juda ajoyib."],["Extreme","jiddiy, ekstremal, xavfli",2,"I don't think extreme sports are safe. I don't like them.","Ekstremal sportlar xavfsiz deb o'ylamayman. Ular menga yoqmaydi."],["First","birinchi",2,"My first lesson in the morning is English.","Tongda birinchi darsim ingliz tili."],["Fit","jismonan sog'lom va baquvvat, tetik",2,"Playing a sport is a great way to get fit.","Biror sport bilan shug'ullanish jismonan sog'lom va baquvvat holatga erishishning zo'r yo'li."],["Healthy","sog'lom; sog'liqqa foydali",2,"It isn't healthy to sit in front of the computer all day.","Kuni bo'yi kompyuter qarshisida o'tirish sog'liqqa zararli."],["Indoor","bino ichida qilinadigan",2,"Playing board games is my favourite indoor activity.","Taxtachada o'ynaladigan o'yinlar o'ynash mening sevimli yopiq (bino ichida o'ynaladigan) mashg'ulotim."],["Last","oxirgi, so'nggi",2,"Did you eat the last piece of pizza?","Oxirgi pitsa bo'lagini yeyib qo'ydingizmi?"],["Outdoor","ochiq havoda qilinadigan, tashqarida qilinadigan",2,"Skiing is a great outdoor activity in the winter.","Chang'i uchish qish faslida ajoyib ochiq havoda bajariladigan mashg'ulotdir."],["Strong","kuchli",2,"Football players have to be fit and strong.","Futbolchilar jismonan tetik va kuchli bo'lishlari shart."],["First","birinchi, birinchi bo'lib, birinchi navbatda",2,"Who came first in the race?","Poygada kim birinchi keldi?"],["Indoors","bino ichida, ichkarida",2,"You play squash indoors but you usually play tennis outdoors.","Raketbol bino ichida o'ynaladi, lekin tennis odatda ochiq havoda o'ynaladi."],["Last","oxirida, oxirgi bo'lib, oxirgi navbatda",2,"I put my shoes on last.","Men oyoq kiyimlarimni oxirgi navbatda kiydim."],["Outdoors","ochiq havoda, tashqarida",2,"When the weather is good, we have a lesson outdoors.","Havo yaxshi bo'lgan vaqtda, biz ochiq havoda dars o'tamiz."],["Do gymnastics/karate/sport/yoga","gimnastika/karate/sport/yoga bilan shug'ullanmoq",3,"My mum always does yoga after work.","Oyim har doim ishdan keyin yoga bilan shug'ullanadi."],["Get/Do some exercise","biroz jismoniy mashq qilmoq",3,"When you have studied for an hour, it's a good idea to get some exercise.","Bir soat dars qilganingizdan keyin, biroz mashq qilib olish yaxshi fikr (= tavsiya etiladi)."],["Get/Keep fit","jismonan sog'lom va baquvvat holatga erishmoq/holatini saqlab qolmoq",3,"Playing a sport is a good way to keep fit.","Biror sport bilan shug'ullanish jismonan sog'lom va baquvvat holatni saqlab qolishning yaxshi yo'li."],["Go for a jog/run/walk","yugurishga/yugurishga/piyoda sayrga chiqmoq",3,"When I want to get some exercise, I usually go for a jog.","Qachonki men biroz mashq qilib olishni istaganimda, men odatda yugurishga chiqaman."],["Go cycling/jogging/skating/skiing/surfing/swimming","velosiped uchishga/yugurishga/konki uchishga/chang'i uchishga/dengizda surfing qilishga/suzishga chiqmoq/bormoq",3,"In the winter, we sometimes go skating on the lake.","Qishda biz ba'zan (muzlagan) daryo ustida konkida uchishga boramiz."],["Play football/basketball","futbol/basketbol o'ynamoq",3,"My brother plays football every Saturday.","Akam har shanba kuni futbol o'ynaydi."],["Ride a bike/a horse/a scooter","velosiped uchmoq/ot minmoq/skuter uchmoq",3,"Do you know how to ride a horse?","Qanday qilib ot minishni bilasizmi?"],["Score a goal","go'l urmoq, natija qayd etmoq",3,"I scored a goal in the football match at school.","Men maktabda futbol musobaqasida bitta go'l urdim."],["Compete","musobaqalashmoq",4,"He regularly competes in races.","U doimiy tarzda poygalarda musobaqalashadi."],["Competition","musobaqa",4,"Did you win the chess competition?","Shaxmat musobaqasida g'olib bo'ldingizmi?"],["Cycle","velosiped uchmoq",4,"I usually cycle home through the park.","Men uyga odatda park oralab velosipedda boraman."],["Cycling","velosiped uchish",4,"Cycling is a good way to get fit.","Velosiped uchish jismonan sog'lom va baquvvat holatga erishishning yaxshi yo'li."],["Cyclist","velosiped uchuvchisi",4,"Drivers need to be careful of cyclists on the road.","Mashina haydovchilari yo'llarda velosiped uchuvchilariga e'tiborli bo'lishlari kerak."],["Fitness","jismonan tetiklik",4,"Walking is good for health and fitness.","Piyoda yurish sog'liq uchun va jismoniy tetiklik uchun foydali."],["Health","sog'liq",4,"Smoking can seriously damage your health.","Chekish sog'liqqa jiddiy zarar yetkazishi mumkin."],["Unhealthy","nosog'lom; sog'liqqa zararli",4,"Tia has a very unhealthy life–she eats all the wrong things and she never exercises.","Tiya juda nosog'lom turmush tarzini yuritadi–u har xil noto'g'ri narsalarni yeydi va hech qachon mashq qilmaydi."],["Healthily","sog'liqqa foydali tarzda",4,"Leah is always unwell because she doesn't eat healthily.","Liya qachon qarasangiz kasal, chunki u sog'liqqa foydali tarzda ovqatlanmaydi."],["Lose","mag'lub bo'lmoq, o'yinni boy bermoq",4,"We lost against Albyn College.","Biz Albin Kollejiga qarshi mag'lub bo'ldik."],["Loser","mag'lub bo'lgan, o'yinni boy bergan odam",4,"It's great when you win a game but someone is always the loser.","O'yinda g'olib bo'lish ajoyib, lekin kimdir har doim mag'lub bo'ladi."],["Strength","kuch",4,"I haven't got the strength to pick up that sofa.","Bu divanni ko'tarishga kuchim yo'q."],["Strongly","qattiq, o'ta, juda",4,"I strongly believe that competition is a good thing.","Raqobat yaxshi narsa ekanligiga qattiq ishonaman."],["Train","shug'ullanmoq, mashq qilmoq",4,"I train in the gym for two hours a day.","Men kuniga 2 soat sport zalida shug'ullanaman."],["Trainers","krasovka: jismoniy mashq qilish jarayonida kiyiladigan oyoq kiyimi",4,"I wear trainers to school because my feet feel more comfortable in them.","Men maktabga krasovkada boraman, chunki oyoqlarim krasovkada o'zini qulayroq his qiladi."],["Well","yaxshi, sog'lom",4,"I don't feel very well.","O'zimni unchalik yaxshi his qilmayapman."],["Unwell","kasal, betob, ahvoli yomon",4,"If you are feeling unwell, go and see the school nurse.","Agar o'zingizni yomon his qilayotgan bo'lsangiz, borib maktab hamshirasiga ko'rining."],["Win","g'olib bo'lmoq, yutmoq",4,"Our team easily won the competition.","Bizning jamoamiz musobaqada osonlik bilan g'alaba qozondi."],["Winner","g'olib",4,"I'm the winner! I came first in the competition!","Men g'olibman! Men musobaqada birinchi bo'lib keldim!"]]},{"n":21,"t":"Rules","c":[["Helmet","kaska: velosiped yoki mototsikl minganda kiyiladigan himoya bosh kiyimi",0,"You have to wear a helmet when you ride your bike.","Velosipedingizni haydayotganingizda kaska (himoya bosh kiyimi) kiyishingiz lozim."],["Jewellery","taqinchoqlar",0,"Bethany has some really nice jewellery but she can't wear it to school.","Besenining bir qancha chiroyli taqinchoqlari bor, lekin uni maktabga kiyib borolmaydi."],["Law","qonun",0,"The police will arrest you if you break the law.","Agar qonunni buzsangiz, politsiya sizni hibsga oladi."],["Litter","axlat",0,"You mustn't drop litter in the street.","Ko'chaga axlat tashlamasligingiz kerak."],["Make-up","makiyaj, pardoz-andoz, oro (berish)",0,"Do your teachers let you wear make-up at school?","Sizning o'qituvchilaringiz maktab hududida yuzingizda pardoz-andoz bo'lishiga yo'l qo'yib beradimi?"],["Notice","e'lon, belgi, ogohlantirish",0,"Can't you see that notice? It says you mustn't enter here!","Anavi belgini ko'rmayapsizmi? Kirmang deb yozib qo'ygan!"],["Police officer","politsiya ofitseri",0,"The police officer arrested the man for fighting in the street.","Politsiya ofitseri erkakni ko'chada mushtlashgani uchun hibsga oldi."],["Road","mashina yo'li",0,"The children have to cross a busy road to get to school.","Bolalar maktabga yetib borish uchun serqatnov mashina yo'lini kesib o'tishlariga to'g'ri keladi."],["Safety/School/Traffic rules","xavfsizlik/maktab/mashina yo'lida harakatlanish qoidalari",0,"Safety rules were disregarded.","Xavfsizlik qoidalari ahamiyatsiz qoldirilgan. The pupils have to read the school rules. – O'quvchilar maktab qoidalarini o'qib chiqishlari shart."],["School uniform","maktab formasi",0,"We don't have to wear school uniform.","Biz maktab formasi kiyishimiz shart emas."],["Seat belt","xavfsizlik kamari",0,"You have to wear a seatbelt on the bus.","Avtobusda xavfsizlik kamarini taqishingiz shart."],["Traffic lights","svetofor",0,"At the next traffic lights, turn right.","Keyingi svetoforda o'ngga buriling."],["Allow","ruxsat bermoq",1,"Do your parents allow you to go to pyjama parties?","Ota-onangiz kechani do'stingiznikida o'tkazadigan bazmlarga borishingizga ruxsat berishadimi?"],["Arrest","hibsga olmoq, qamoqqa olmoq",1,"The police arrested a man for taking things from a shop.","Politsiya bir kishini do'kondan narsa olgani (= o'g'irlagani) uchun hibsga oldi."],["Drive","mashina haydamoq",1,"I'm going to learn to drive a car when I'm 17.","17 yosh bo'lganimda mashina haydashni o'rganmoqchiman."],["Drop","tashlamoq",1,"Don't drop litter in the street!","Ko'chaga axlat tashlamang!"],["Enter (a place)","(joyga) kirmoq",1,"You can't enter the building. It's not open now.","Binoga kira olmaysiz. Hozir ochiq emas."],["Fight","urushmoq",1,"You can't fight at school. The teachers will get very angry.","Maktabda mushtlashishingiz mumkin emas. O'qituvchilarning juda jahli chiqadi."],["Let","biror narsa qilishiga qo'yib bermoq, yo'l qo'ymoq, ruxsat bermoq",1,"Sometimes my mum lets me sleep at a friend's house.","Ba'zida onam do'stimning uyida uxlashimga ruxsat beradi."],["Park","mashinani joylamoq/qo'ymoq, parkovka qilmoq",1,"You mustn't park your car in front of the hospital.","Mashinangizni shifoxona to'g'risiga qo'ymasligingiz shart."],["Throw away","axlatga tashlamoq",1,"Don't throw that away! I want it.","Uni axlatga tashlab yubormang! U menga kerak."],["Wear","kiymoq",1,"Cyclists must wear a helmet.","Velosipedchilar kaska kiyishlari shart."],["Careful","diqqatli, e'tiborli, ehtiyotkor",2,"Be careful when you go out at night.","Kechasi ko'chaga chiqqaningizda ehtiyotkor bo'ling."],["Dangerous","xavfli",2,"I don't like walking in the park at night. It's dangerous.","Men kechasi parkda sayr qilishni yoqtirmayman. Bu xavfli."],["Necessary","muhim, kerak, shart",2,"It isn't necessary to wear special clothes to my party.","Mening bazmimga maxsus kiyimlar kiyish shart emas."],["Noisy","shovqinli",2,"The cars in the city are very noisy!","Shahardagi mashinalar juda shovqinli!"],["Polite","muloyim, xushmuomala",2,"I'm always polite–I always say \"please\" and \"thank you\".","Men doimo xushmuomalaman–har doim \"marhamat\" va \"rahmat\" so'zlarini aytaman."],["Quiet","jimjit, shovqindan holi",2,"It's quiet in my town. When I lived in the city, it was very noisy.","Mening shaharcham shovqindan holi. Katta shaharda yashagan vaqtimda juda shovqinli edi."],["Safe","xavfsiz, xavfdan holi",2,"Don't be frightened. You're safe now.","Qo'rqmang. Endi xavfdan holisiz."],["Always","har doim, doimo",2,"I am always careful when I walk in the street.","Ko'chada yurganimda, men doimo ehtiyotkor bo'laman."],["Against the rules/the law","qoidalarga zid/qonunga zid",3,"You can't use mobile phones in the classroom–it's against the rules.","Sinfda uyali telefondan foydalana olmaysiz–bu qoidalarga zid."],["Be late/in time (for)","(biror narsaga) kechikmoq/ulgurmoq",3,"I'm never late for school.","Men hech qachon maktabga kechikmayman."],["Break (the rules/the law)","(qoidalarni/qonunni) buzmoq",3,"When we break the rules at our school, the teachers call our parents.","Maktabimizda qoidalarni buzganimizda, o'qituvchilar ota-onamizga qo'ng'iroq qilishadi."],["No running/talking","yugurmang/gaplashmang",3,"No talking! This is an exam!","Gaplashmang! Bu imtihon!"],["(Not) Allowed to do","biror narsa qilishga ruxsat beril(ma)gan, biror narsa qilish mumkin (emas)",3,"We're not allowed to run in the school buildings.","Biz maktab binolarida yugurishimiz mumkin emas."],["Tell a lie","yolg'on gapirmoq",3,"I can't tell a lie. I broke the window, not Josh.","Men yolg'on gapirolmayman. Derazani men sindirdim, Jo'sh emas."],["Tell the truth","haqiqatni gapirmoq, rostini aytmoq",3,"I want you to tell the truth now. Did you cheat in the test?","Hozir sizdan haqiqatni gapirishingizni istayman. Imtihonda g'irromlik qildingizmi?"],["Turn left/right","chapga/o'ngga qayrilmoq, burilmoq",3,"When you come out of the school, turn left and I'll meet you there.","Maktabdan chiqqaningizda, chapga qayriling va men sizni o'sha yerda kutib olaman."],["Apology","kechirim, uzr",4,"We received a letter of apology.","Biz kechirim xati qabul qildik."],["Apologise","kechirim so'ramoq",4,"I apologise for what I said. I'm really sorry.","Men aytgan gapim uchun kechirim so'rayman. Juda afsusdaman."],["Care","parvarish, qarash, ehtiyot qilish",4,"With proper care, the plants may last for fifty years.","To'g'ri parvarish bilan, bu o'simliklar 50 yil turishi mumkin."],["Care","qayg'urmoq",4,"I care what you do!","Siz nima qilishingiz to'g'risida men qayg'uraman! (= Siz nima qilayotganingiz menga qiziq!)"],["Careless","ehtiyotsiz, bee'tibor",4,"Don't be careless at work.","Ishda bee'tibor bo'lmang."],["Carefully","ehtiyotkorlik bilan",4,"Hold that knife carefully. Don't cut your hand.","Pichoqni ehtiyotkorlik bilan ushlang. Qo'lingizni kesib olmang."],["Carelessly","ehtiyotsizlik bilan",4,"I was playing carelessly and I broke the window.","Men ehtiyotsizlik bilan o'ynayotgandim va derazani sindirib qo'ydim."],["Danger","xavf",4,"We weren't in any danger.","Biz hech qanday xavf ostida emasdik."],["Dangerously","xavfli tarzda",4,"Dad never drives dangerously.","Dadam hech qachon xavfli tarzda mashina haydamaydi."],["Driver","haydovchi",4,"The driver of the car wasn't looking at the road.","Mashina haydovchisi yo'lga qaramayotgan edi."],["Enter","kirmoq",4,"Knock before you enter.","Kirishingizdan avval taqillating."],["Entrance","kirish (eshigi, joyi)",4,"This is the entrance to the school–this is where we go in every day.","Bu maktabga kirish joyi–biz har kuni ichkariga kiradigan joy shu yer."],["Lie","yolg'on gapirmoq, aldamoq",4,"Don't lie to me!","Menga yolg'on gapirmang!"],["Liar","yolg'onchi, aldoqchi",4,"I know Kira is a liar because she said some things that were untrue.","Kira yolg'onchi ekanligini bilaman chunki u bir qancha yolg'on bo'lgan narsalarni aytdi."],["Noise","shovqin",4,"Don't make a noise.","Shovqin chiqarmang."],["Noisily","shovqin bilan, shovqin chiqarib, shovqinli tarzda",4,"My sister walked in the room noisily and woke me up.","Singlim shovqin chiqarib xonaga kirib keldi va meni uyg'otdi."],["Impolite","qo'rs, qo'pol",4,"If you don't speak, people will think you are being impolite.","Agar gapirmasangiz, odamlar sizni qo'pol bo'lyapti deb o'ylaydilar."],["Quiet","jimjit, shovqindan holi, tinch",4,"'Be quiet,' said the teacher.","'Jim bo'ling,' dedi o'qituvchi."],["Quietly","shovqin chiqarmay, shovqinsiz tarzda",4,"Mum's sleeping, so talk quietly.","Oyim uxlayaptilar, shuning uchun shovqin chiqarmay gapiring."],["True","rost, to'g'ri",4,"Stop telling lies! I want to hear what's true!","Yolg'on gapirishni to'xtating! Rost narsani eshitishni xohlayman!"],["Untrue","yolg'on, noto'g'ri",4,"What you said was untrue. It was a lie.","Aytgan gapingiz noto'g'ri edi. U yolg'on edi."],["Truth","haqiqat",4,"Do you think she's telling the truth?","U haqiqatni aytyapti deb o'ylaysizmi?"]]},{"n":24,"t":"Food And Shopping","c":[["Barbecue","barbekyu: ochiq havoda cho'g' ustiga qo'yilgan setka ustida go'sht pishirish va uni tamaddi qilish",0,"Barbecues are great! I love eating outdoors.","Barbekyular juda ajoyib! Men ochiq havoda ovqatlanishni yoqtiraman."],["Credit card/Cash","plastik kartochka/naqd pul",0,"Do you want to pay by credit card or in cash?","Plastik kartochkasi orqali to'lashni istaysizmi yoki naqd puldami?"],["Coffee","kofe, qahva",0,"It's a bad idea to drink coffee in the evening–you won't sleep.","Oqshomda qahva ichish yomon fikr–uxlamaysiz (= uxlatmaydi)."],["Juice","sharbat, so'k",0,"Do you want water or juice to drink?","Ichishga suv xohlaysizmi yoki sharbat?"],["Lemonade","limonad",0,"My mum makes lemonade with fresh lemons, water and sugar.","Oyim yangi limon, suv va shakar bilan limonad tayyorlaydi."],["Milk","sut",0,"I don't eat at night but I sometimes drink a glass of milk.","Men kechasi ovqatlanmayman lekin ba'zida bir stakan sut ichaman."],["Tea","choy",0,"People drink a lot of tea in England.","Angliyada ko'p choy ichishadi."],["Water","suv",0,"We must drink water every day.","Biz har kuni suv ichishimiz kerak."],["Apple","olma",0,"I love fruit and red apples are my favourite.","Menga mevalar yoqadi va qizil olmalar mening eng yoqtirganim."],["Banana","banan",0,"A banana is a long, yellow fruit.","Banan - bu uzun, sariq meva."],["Biscuit","pechenye",0,"I like chocolate biscuits.","Menga shokoladli pechenyelar yoqadi."],["Bread","non",0,"We haven't got any bread, so I can't make a sandwich.","Bizda hech qancha non yo'q, shuning uchun sendvich tayyorlay olmayman."],["Burger","gamburger",0,"When we go into town, we sometimes eat a burger and chips.","Shaharga yo'limiz tushganida (= borganimizda), ba'zan gamburger va chips yeymiz."],["Butter","saryog'",0,"Don't put a lot of butter on your bread–it's not healthy.","Noningizni ustiga haddan tashqari ko'p saryog' surib yubormang–bu sog'liqqa zarar."],["Cake","to'rt",0,"People often have a cake when they have a birthday party.","Odamlarning tug'ilgan kuni bo'lganida, ular ko'pincha to'rt olishadi."],["Carrot","sabzi",0,"A carrot is a long, orange vegetable.","Sabzi - bu uzun, olovrang sabzavot."],["Cheese","pishloq",0,"Do you want cheese on the pizza?","Pitsangizni ustida pishloq bo'lishini istaysizmi?"],["Chicken","tovuq go'shti",0,"We cook chicken on Sundays and have it with potatoes and carrots.","Biz shanba kunlari tovuq pishiramiz va uni kartoshka va sabzilar bilan yeymiz."],["Chips","chips, salyonka: yog'da parrak-parrak shaklda qovurilgan kartoshkalar",0,"Chips are fried potatoes.","Chips - bu qovurilgan kartoshkalar."],["Chocolate","shokolad",0,"Chocolate is very nice but it has a lot of sugar in it.","Shokolad juda yaxshi lekin uning ichida ko'p shakar bo'ladi."],["Cream","krem",0,"We sometimes have fresh fruit with cream on it.","Biz ba'zida yangi mevalarni ustiga krem surib yeymiz."],["Egg","tuxum",0,"There aren't any eggs, so we can't make an omelette for lunch.","Hech qancha tuxum qolmagan, shuning uchun tushlikka quymoq qila olmaymiz."],["Fish","baliq go'shti",0,"They say it's healthy to eat lots of fish.","Odamlar aytishicha ko'p baliq yeyish sog'liqqa foydali."],["Fruit","meva, mevalar",0,"I always eat a little fruit every day–usually an apple.","Men har kuni doimo ozgina meva yeyman–odatda bitta olma."],["Ice cream","muzqaymoq",0,"I love eating ice cream on a hot summer day.","Men issiq yoz kunida muzqaymoq yeyishni yoqtiraman."],["Jam","murabbo, jem",0,"For breakfast, I have bread with butter and jam.","Men nonushtaga saryog'li non va murabbo yeyman."],["Lemon","limon",0,"Lemons are sour, yellow fruit.","Limonlar - bu nordon, sariq meva."],["Meat","go'sht",0,"It isn't healthy to eat meat every day.","Har kuni go'sht yeyish sog'liq uchun zararli."],["Oil","yog'",0,"You use oil to fry things like meat, fish and potatoes.","Yog'ni go'sht, baliq va kartoshka singari narsalarni qovurish uchun ishlatasiz."],["Omelette","quymoq, tuxumli quymoq",0,"Dad makes great omelettes. He uses milk, cheese and six eggs.","Dadam zo'r quymoq pishiradi. U sut, pishloq va oltita tuxumdan foydalanadi."],["Onion","piyoz",0,"Some people don't like onions on their pizza.","Ba'zi odamlar pitsalarini ustida piyoz bo'lishini yoqtirmaydi."],["Orange","apelsin",0,"Oranges are round fruit. You can eat them or make juice with them.","Apelsinlar dumaloq mevalar. Siz ularni yeyishingiz mumkin yoki ulardan sharbat tayyorlashingiz mumkin."],["Pasta","makaronli ovqatlar",0,"Spaghetti is my favourite kind of pasta.","Spagetti mening sevimli makaronli taomim."],["Pizza","pitsa",0,"Pizza is a great fast food. It came from Italy.","Pitsa ajoyib tez tayyor bo'ladigan ovqat. U Italiyadan kelib chiqqan."],["Potato","kartoshka",0,"You can boil potatoes, fry them or bake them.","Kartoshkalarni suvda qaynatishingiz, yog'da qovurishingiz yoki duxovkada pishirishingiz mumkin."],["Rice","guruch",0,"In places like China and Indonesia, they eat a lot of rice.","Xitoy va Indoneziya singari joylarda ko'p guruch yeyishadi."],["Salad","salat",0,"A fresh salad is a healthy thing to eat for dinner.","Svejiy salat (= svejiy masalliqlardan tayyorlangan) kechki ovqatga yeyish uchun sog'liqqa foydali narsa."],["Sandwich","buterbrod, sendvich: ikki bo'lak non o'rtasiga ta'bga qarab go'sht, pishloq, tuxum va sabzavotlar solingan yengil taom",0,"When I'm hungry, I make a cheese sandwich.","Qornim ochganida, men pishloqli sendvich tayyorlayman."],["Tomato","pomidor",0,"Mum has lots of lovely red tomatoes growing in her garden.","Oyimning bog'ida juda ko'p chiroyli qizil pomidorlar o'syapti."],["Vegetable","sabzavot",0,"Potatoes and carrots are vegetables.","Kartoshka va sabzilar sabzavotlardir."],["Breakfast","nonushta",0,"They say it isn't healthy to miss breakfast.","Odamlar aytishicha nonushta qilmaslik sog'liq uchun zararli."],["Lunch","tushlik",0,"We eat our lunch at school at 1 pm.","Biz tushlikni maktabda soat 1 da yeymiz."],["Dinner","kechki ovqat",0,"Dinner is the evening meal. We have dinner at about 8 pm.","Kechki ovqat - bu oqshomda yeyiladigan ovqat. Biz taxminan kechki soat 8 da kechki ovqatni yeymiz."],["First/Main course","birinchi taom/asosiy taom",0,"I think I'll have pasta for my main course.","Menimcha asosiy taom uchun men makaronli taom yeyman."],["Dessert","desert: asosiy ovqatdan keyin yeyiladigan shirinlik",0,"That was a great meal. Do you want some ice cream for dessert?","Bu ajoyib ovqat bo'libdi. Desert uchun ozgina muzqaymoq istaysizmi?"],["Chef","bosh oshpaz",0,"I love cooking food. I think I want to become a chef.","Menga ovqat pishirish yoqadi. O'ylashimcha men bosh oshpaz bo'lishni xohlayman."],["Cook","oshpaz",0,"I'm a good cook. I want to work in a restaurant.","Men yaxshi oshpazman. Men restoranda ishlashni xohlayman."],["Customer","xaridor",0,"There were a lot of customers in the shop, so I left.","Do'konda juda ko'p xaridorlar bor edi, shuning uchun men chiqib ketdim."],["Shop assistant","sotuvchi",0,"The shop assistant helped me choose what to buy.","Sotuvchi menga nima sotib olishimni tanlashga yordam berdi."],["Waiter","ofitsiant",0,"Ask the waiter for a glass of water.","Ofitsiantdan bir stakan suv so'rang."],["Waitress","ofitsiantka",0,"The waitress was very polite when we ordered our food.","Biz buyurtma berganimizda, ofitsiantka juda xushmuomala bo'ldi."],["Piece of bread/cake","bir bo'lak non/to'rt",0,"Some people always want a piece of bread with their dinner.","Ba'zi odamlar har doim kechki ovqatlari bilan birga bir bo'lak non ham xohlashadi (= non bilan yeyishadi)."],["Price","narx",0,"Can you tell me the price of these oranges, please?","Mana bu apelsinlarning narxini menga aytib yubora olasizmi, iltimos?"],["Bakery","nonvoyxona, qandolat do'koni: non mahsulotlari, to'rt, bulochka, pishiriqlar tayyorlanadigan joy",0,"We buy fresh bread from the bakery every morning.","Biz har tongda nonvoyxonadan yangi yopilgan non sotib olamiz."],["Bookshop","kitob do'koni",0,"I bought my friend a book from the bookshop.","Men kitob do'konidan do'stim uchun bir kitob sotib oldim."],["Chemist's","dorixona, apteka",0,"At the chemist's you can buy medicines and beauty products.","Dorixonadan dori va go'zallik mahsulotlari sotib olishingiz mumkin."],["Department store","univermag, savdo markazi: birgina katta do'kon ichida barcha turdagi mahsulotlar sotiladi",0,"They sell many different things in a department store.","Univermagda juda ko'p turli-tuman narsalar sotishadi."],["Shopping centre","savdo majmuasi: turli-tuman mahsulotlar sotishga mo'ljallangan ko'plab do'konlardan tashkil topgan bo'ladi",0,"The shopping centre in town has many different shops.","Shahardagi savdo majmuasida ko'plab turli-tuman do'konlar bor."],["Supermarket","supermarket",0,"We buy most of our food from the supermarket.","Biz ko'pchilik oziq-ovqatimizni supermarketdan sotib olamiz."],["Bottle","butilka, shisha idish, baklashka",0,"Can you buy me a bottle of water to drink?","Ichish uchun menga bir baklashka suv sotib ola olasizmi?"],["Bowl","kosa, chuqurcha idish",0,"We always have a bowl of fruit in the kitchen.","Oshxonamizda har doim chuqurcha idishda mevalar turadi."],["Cooker","gaz plitasi, duxovka",0,"Most homes have a cooker in the kitchen.","Ko'pchilik uylarning oshxonasida gaz plitasi bor."],["Cup","chashka, krushka",0,"Do you want a cup of coffee?","Bir krushka qahva xohlaysizmi?"],["Dish","idish-tovoq",0,"I often help my mum wash the dishes.","Men ko'pincha oyimga idish-tovoqlarni yuvishga yordam beraman."],["Fork","vilka",0,"We eat with a knife and fork.","Biz pichoq va vilka bilan yeymiz."],["Fridge","muzlatgich",0,"There's cold milk in the fridge.","Muzlatgichda sovuq sut bor."],["Knife","pichoq",0,"I need a knife to cut this fruit.","Bu mevani kesish uchun menga pichoq kerak."],["Plate","tarelka, likopcha",0,"Can I have a plate for this piece of pizza, please?","Bu pitsa bo'lagi uchun bitta likopcha olsam bo'ladimi, iltimos?"],["Spoon","qoshiq",0,"I like to eat ice cream from a bowl using a spoon.","Men muzqaymoqni qoshiq ishlatib idishdan yeyishni yoqtiraman."],["Buy","sotib olmoq",1,"What will we buy Helen for her birthday?","Helenga tug'ilgan kuni uchun nima sotib olamiz?"],["Boil","suvda qaynatib pishirmoq",1,"I sometimes boil an egg for breakfast.","Men ba'zida nonushta uchun tuxum qaynataman."],["Grill","grillda pishirmoq, qo'rada pishirmoq, qovurmoq",1,"When you grill meat, be careful not to burn it.","Go'shtni qo'rada pishirganingizda, uni kuydirib yubormaslikka e'tibor bering."],["Fry","yog'da qovurmoq",1,"You need oil to fry food and it's not very healthy.","Yog' ovqatni qovurish uchun kerak va u sog'liqqa u qadar foydali emas."],["Bake","pechkada pishirmoq, duxovkada pishirmoq",1,"On special days, my grandmother usually bakes a cake.","Maxsus kunlarda, buvim odatda to'rt pishiradilar."],["Cut","kesmoq, to'g'ramoq",1,"You have to cut the potatoes to make chips.","Chips tayyorlash uchun, kartoshkalarni kesishingiz kerak."],["Drink","ichmoq",1,"It's healthy to drink lots of water every day.","Har kuni ko'p suv ichish sog'liqqa foydali."],["Eat","yemoq",1,"I don't always have time to eat breakfast.","Har doim ham nonushta qilish uchun vaqtim bo'lavermaydi."],["Eat out","kafe yoki restoranda ovqatlanmoq",1,"My family often eats out. We like going to different restaurants.","Oilam tez-tez restoranda ovqatlanib turadi. Biz turli xil restoranlarga borishni yoqtiramiz."],["Order","buyurtma bermoq",1,"The waitress said, \"Are you ready to order your food?\"","Ofitsiantka aytdi: \"Buyurtma berishga tayyormisiz?\""],["Sell","sotmoq",1,"They sell fresh fruit in the shop in Elm Street.","Elm ko'chasidagi do'konda yangi uzilgan mevalar sotishadi."],["Taste","ta'tib ko'rmoq, mazasini ko'rmoq",1,"Can I taste your ice cream? I want to order the same.","Sizning muzqaymog'ingizni ta'tib ko'rsam bo'ladimi? Men ham xuddi shunaqasidan buyurtma berishni istayman."],["Wash up","idish-tovoqlarni yuvmoq",1,"The best thing about eating out is that you don't have to wash up!","Restoranda ovqatlanishning eng yaxshi tarafi shuki siz idish-tovoqlarni yuvishingizga to'g'ri kelmaydi."],["Cheap","arzon",2,"Cheap food isn't always bad.","Arzon yegulik har doim ham yomon bo'lavermaydi."],["Closed","yopiq",2,"The shops are closed today because it's Sunday.","Do'konlar bugun yopiq chunki bugun yakshanba."],["Expensive","qimmat",2,"The meat in the shop was very expensive so I bought fish.","Do'konda go'sht juda qimmat ekan, shuning uchun baliq sotib oldim."],["Hungry","qorni och",2,"I'm really hungry. Is there any food?","Men juda ochman. Qandaydir yegulik bormi?"],["Open","ochiq",2,"Is the shop open? I need to buy something for breakfast.","Do'kon ochiqmi? Men nonushta uchun biror narsa sotib olishim kerak."],["Salty","tuzli, sho'r, sho'rtang",2,"Fast food is really salty. I always feel thirsty after eating it.","Tez tayyor bo'ladigan ovqat juda sho'rtang bo'ladi. Men har doim uni yeganimdan so'ng chanqayman."],["Sweet","shirin",2,"Chocolate and ice cream taste very sweet.","Shokolad va muzqaymoqning mazasi juda shirin."],["Thirsty","chanqagan",2,"I was really thirsty after the race–I drank two litres of water!","Poygadan keyin juda chanqagan edim–ikki litr suvni ichib yubordim!"],["Do the washing-up","idish-tovoqlarni yuvmoq",3,"If you cook, I'll do the washing-up.","Agar siz ovqat pishirsangiz, men idish-tovoqlarni yuvaman."],["Go on a picnic","piknik chiqmoq: tabiat qo'ynida ovqatlanmoq va vaqt o'tkazmoq",3,"It's a nice day. Let's go on a picnic.","Bugun kun ajoyib. Keling piknikka chiqamiz."],["Go shopping","xarid uchun bormoq",3,"We usually go shopping for food on Saturday mornings.","Biz odatda oziq-ovqat xarid qilishga shanba kunlari tongda boramiz."],["Have a snack","yengil tamaddi qilib olmoq",3,"We eat dinner late so when I come home from school, I have a small snack.","Biz kechki ovqatni kech yeymiz, shuning uchun men maktabdan uyga kelganimda, yengil tamaddi qilib olaman."],["Have breakfast/lunch/dinner","nonushta qilmoq/tushlik qilmoq/kechki ovqatni yemoq",3,"We have lunch at school. It's usually very nice.","Biz maktabda tushlik qilamiz. U odatda juda yaxshi."],["Make a cup of tea/a sandwich","bir chashka choy tayyorlamoq/bitta buterbrod tayyorlamoq",3,"When mum comes home from work, I usually make her a cup of tea.","Oyim ishdan uyga kelganlarida, men odatda ularga bir chashka choy tayyorlab beraman."],["Pay for something in cash/by credit card","biror narsa uchun naqd pul/plastik kartochka orqali to'lamoq",3,"I never pay for things by credit card. I always pay in cash.","Men hech qachon narsalar uchun plastik kartochka orqali pul to'lamayman. Har doim naqd pulda to'layman."],["Spend money","pul sarflamoq",3,"I usually spend my money on sweets and books.","Men odatda pulimni shirinliklar va kitoblarga sarflayman."],["Assist","yordam bermoq",4,"Your job will be to assist the production manager.","Sizning ishingiz ishlab chiqarish boshqaruvchisiga yordamlashish bo'ladi."],["Assistant","yordamchi",4,"My mum works as an assistant to the manager.","Mening oyim ish boshqaruvchi yordamchisi bo'lib ishlaydi."],["Cook","pishirmoq",4,"Where did you learn to cook?","Ovqat pishirishni qayerda o'rgangansiz?"],["Cooking","pishirish",4,"I love cooking–I always make dinner in my house.","Menga ovqat pishirish yoqadi–uyda doim kechki ovqatni men tayyorlayman."],["Cooker","gaz plitasi",4,"In the kitchen, there's a fridge, a cooker and a big table.","Oshxonada muzlatgich, gaz plitasi va katta stol bor."],["Close","yopmoq",4,"It's dark now—let's close the curtains.","Qorong'u tushdi–keling pardalarni yopamiz."],["Fried","yog'da qovurilgan",4,"We're having fried chicken for dinner.","Kechki ovqatga qovurilgan jo'ja yeyapmiz."],["Hunger","ochlik",4,"Thousands of people have died of hunger.","Minglab odamlar ochlikdan halok bo'lishdi."],["Salt","tuz",4,"Pass the salt, please.","Tuzni uzatib yuboring, iltimos."],["Salty","tuzli, sho'rtang, sho'r",4,"That pizza was very salty. I drank three glasses of water after eating it.","Bu pitsa juda sho'rtang ekan. Uni yeganimdan keyin, uch stakan suv ichib yubordim."],["Shop","xarid qilmoq",4,"He likes to shop at the local market.","U mahalliy bozorda xarid qilishni yoqtiradi."],["Shopping","xarid qilish",4,"My favourite activity is shopping–I love buying things.","Mening sevimli mashg'ulotim bu xarid qilish–menga narsalar sotib olish yoqadi."],["Shopper","xaridor",4,"There are a lot of shoppers in the town centre today.","Bugun shahar markazida juda ko'p xaridorlar bor."],["Thirst","chanqoqlik, suvga tashnalik",4,"Thousands are dying of thirst.","Minglab odamlar suvga tashnalikdan halok bo'lyapti."]]},{"n":27,"t":"Character And Appearance","c":[["Appearance","tashqi ko'rinish",0,"Owen doesn't care about his appearance. His clothes are often dirty.","Oven tashqi ko'rinishi haqida qayg'urmaydi (= qanday ko'rinishi unga qiziq emas). Uning kiyimlari ko'pincha kir bo'ladi."],["Build","qomat, gavda",0,"I haven't got the right height or build to become a police officer.","Politsiya ofitseri bo'lish uchun kerakli bo'y yoki gavdaga ega emasman."],["Character","fe'l-atvor, xulq, xarakter",0,"A person's character is important. I can't be friends with someone rude.","Insonning fe'l-atvori muhim. Men qo'pol kimsa bilan do'st bo'la olmayman."],["Face","yuz, chehra",0,"The first thing I look at is a person's face.","Men nazar tashlaydigan birinchi narsa bu insonning yuzi."],["Friendship","do'stlik (rishtasi)",0,"Friendship is very important to me. I am very loyal to my friends.","Do'stlik rishtasi men uchun juda muhim. Men do'stlarimga juda sodiqman."],["Height","bo'y",0,"My height is 1 metre 67 cm.","Mening bo'yim 1 metr va 67 sentimetr."],["Personality","shaxsiyat, o'ziga xos fe'l-atvor, xususiyat",0,"I choose my friends because of their personality.","Men do'stlarimni o'ziga xos fe'l-atvori uchun tanlayman."],["Cat","mushuk",0,"My pet cat Jason has got a long tail.","Mening xonaki mushugim Jeysnning uzun dumi bor."],["Dog","it, kuchuk",0,"I take my dog for his daily walk after school.","Men maktabdan keyin kuchugimni har kunlik sayriga olib chiqaman."],["Fish","baliq",0,"Ava keeps fish as pets. They live in a bowl in her living room.","Eyva uy jonvori sifatida baliq boqadi. Ular uning mehmonxonasida shisha idishda yashaydi."],["Hamster","hamyak: uy sichqoni",0,"Liam feeds his pet hamster when he gets up in the morning.","Liyem tongda uyg'onganida, hamyakini ovqatlantiradi."],["Parrot","to'ti",0,"You can teach your pet parrot to talk.","To'tingizni gapirishga o'rgatishingiz mumkin."],["Rabbit","quyon",0,"We have a pet rabbit. It lives in the garden.","Uyimizda quyonimiz bor. U bog'da yashaydi."],["Tortoise","toshbaqa",0,"I'd like to keep a tortoise as a pet.","Men uy hayvoni sifatida toshbaqa boqishni xohlardim."],["Smile","tabassum, jilmayish, kulgu",0,"My mum always has a smile on her face. She never frowns.","Oyimning yuzlarida har doim tabassum bo'ladi. U hech qachon xo'mraymaydi."],["Weight","og'irlik",0,"The doctor wrote down my age, height and weight.","Shifokor mening yoshimni, bo'yimni va og'irligimni yozib oldi."],["Admire","qoyil qolmoq, hurmat qilmoq",1,"I admire my mum because she's very good at her job.","Men oyimga qoyil qolaman chunki u o'z ishida usta."],["Frown","qovog'ini solmoq, xo'mraymoq, o'qraymoq, shumshaymoq",1,"Why are you frowning? You look sad.","Nima uchun xo'mrayyapsiz? Xafa ko'rinasiz."],["Get on with","yaxshi chiqishmoq, yaxshi munosabatda bo'lmoq",1,"Do you get on with your relatives or do you fight?","Qarindoshlaringiz bilan yaxshi munosabatdamisiz yoki urushasizlarmi?"],["Look after","vaqtinchalik qarab turmoq, g'amxo'rlik qilmoq, boqmoq",1,"I'm looking after my best friend's dog while she's on holiday.","Eng yaxshi do'stim ta'tilda bo'lgan paytida, men uning itiga qarab turyapman."],["Love","sevmoq, yoqtirmoq",1,"I love my pets very much.","Men uy hayvonlarimni juda yaxshi ko'raman."],["Prefer","afzal ko'rmoq",1,"I prefer cats to dogs. I don't like dogs very much.","Men itlardan ko'ra mushuklarni afzal ko'raman. Itlar menga uncha yoqmaydi."],["Respect","hurmat qilmoq",1,"You must respect how other people feel. We are not all the same.","Boshqalar qanday his qilishini hurmat qilishingiz kerak. Biz hammamiz bir xil emasmiz."],["Share","birga ishlatmoq, birga foydalanmoq",1,"My brother shares a house with three of his friends.","Mening akam uyidan uchta do'sti bilan birga foydalanadi."],["Smile","jilmaymoq, tabassum qilmoq",1,"When you smile, it makes other people feel more comfortable around you.","Siz tabassum qilganingizda, atrofingizdagi odamlar o'zlarini qulayroq his qiladilar."],["Take after","ko'rinishi o'xshamoq",1,"I take after my dad. We have the same hair and eyes.","Men dadamga o'xshayman. Bizning sochimiz va ko'zlarimiz bir xil."],["Trust","ishonmoq",1,"I can trust my friends. They're all very reliable and loyal.","Men do'stlarimga ishona olaman. Ularning bari juda ishonchli va sodiq."],["Cute","yoqimtoy, chiroyli",2,"My pet hamster is really cute.","Mening hamyakim juda ham yoqimtoy."],["Good-looking","chiroyli",2,"George is really good-looking. He's got fair hair and blue eyes.","Jo'rj juda chiroyli. Uning sochi och rangli va ko'zlari moviy."],["Kind","mehribon",2,"You must always be kind to people and animals.","Odamlar va hayvonlarga nisbatan doimo mehribon bo'lishingiz kerak."],["Loyal","sodiq, vafodor",2,"It's important that my friends are loyal and reliable.","Do'stlarim sodiq va ishonchli ekanligi muhim."],["Polite","xushmuomala",2,"When you have a nice personality, you are always polite to people.","Yaxshi fe'l-atvorga ega bo'lsangiz, siz doim odamlarga xushmuomala bo'lasiz."],["Reliable","ishonsa bo'ladigan, ishonchli",2,"Reliable people are never late.","Ishonsa bo'ladigan odamlar hech qachon kechikishmaydi."],["Short","bo'yi past; kalta",2,"My pet dog's got very short legs.","Mening kuchugimning juda kalta oyoqlari bor."],["Slim","chiroyli ravishda ozg'in, xipcha, xushbichim",2,"Peter is slim because he gets a lot of exercise and he doesn't eat much.","Piter xushbichim chunki u ko'p mashq qiladi va ko'p ovqat yemaydi."],["Tall","bo'yi baland, novcha",2,"Toby is very tall. That helps him when he plays basketball.","To'bi juda novcha. U basketbol o'ynaganida, bu unga yordam beradi."],["Care about","haqida qayg'urmoq",3,"Charlotte doesn't care about sport–she's not interested in it.","Sharlet sport haqida qayg'urmaydi–u bunga qiziqmaydi."],["Have a good sense of humour","hazil-mutoyibani yaxshi tushunmoq: hazil qila olmoq va hazil qilinganda uni tushunib kula olmoq",3,"Owen's a funny boy. He has a good sense of humour.","Oven kulgili bola. U hazil-mutoyibani yaxshi tushunadi."],["Have a lot of fun with","bilan birga mazza qilmoq, maroq bilan vaqt o'tkazmoq",3,"I have a lot of fun with my brother. We get on very well.","Men ukam bilan mazza qilaman. Biz yaxshi chiqishamiz."],["Have short/long/straight/curly/wavy/dark/light/fair hair","sochi kalta/uzun/tekis/jingalak/to'lqinsimon/to'q rangli/och rangli/och rangli bo'lmoq",3,"I have short, dark, curly hair and my brother's got long, fair, wavy hair.","Mening sochim kalta, to'q rangli va jingalak, ukamniki esa uzun, och rangli va to'lqinsimon."],["Look different/great/the same","boshqacha/ajoyib/bir xil ko'rinmoq",3,"They are sisters but they look very different.","Ular opa-singillar, lekin ular boshqacha ko'rinishadi."],["Make someone laugh","biror kimni kuldirmoq",3,"Harrison makes me laugh–he's a funny guy.","Harisen meni kuldiradi–u kulgili bola."],["Take care of","ga g'amxo'rlik qilmoq, qarab turmoq",3,"My friend, Connor, takes care of my dog for me when I'm on holiday.","Men ta'tilda bo'lgan paytimda, do'stim Koner itimga g'amxo'rlik qilib turadi."],["Worry about","haqida tashvishlanmoq, xavotirlanmoq",3,"Please stay safe when you're travelling. You know I worry about you.","Iltimos, sayohat paytida xavfsiz bo'ling. Bilasiz, men siz haqingizda tashvishlanaman."],["Admiration","qoyil qolish, hurmat, havas",4,"I have a lot of admiration for people who help others. It's a great thing to do.","Boshqalarga yordam beruvchi odamlarga nisbatan juda hurmatim baland. Bu juda yaxshi ish."],["Appear","ko'rinmoq",4,"Her dead mother appeared to her in a dream.","Uning vafot etgan onasi tushida unga ko'rindi."],["Care","parvarish, qarash, ehtiyot qilish",4,"Some people were badly injured and needed medical care.","Ba'zi odamlar og'ir jarohatlangandi va tibbiy parvarishga muhtoj edi."],["Care","qayg'urmoq",4,"I care what you do!","Siz nima qilishingiz to'g'risida men qayg'uraman! (= Siz nima qilayotganingiz menga qiziq!)"],["Caring","g'amxo'r, mehribon",4,"Mum's a very caring person.","Oyim juda g'amxo'r insonlar."],["Careful","ehtiyotkor, e'tiborli, diqqatli",4,"Be careful when you walk near the road.","Mashina yo'li yaqinida yurganda ehtiyotkor bo'ling."],["Careless","bee'tibor, beparvo",4,"Don't be careless at work.","Ishda bee'tibor bo'lmang."],["Carefully","ehtiyotkorlik bilan",4,"Hold that knife carefully. Don't cut your hand.","Pichoqni ehtiyotkorlik bilan ushlang. Qo'lingizni kesib olmang."],["Carelessly","bee'tiborlik bilan, beparvolik bilan",4,"I was playing carelessly and I broke the window.","Men ehtiyotsizlik bilan o'ynayotgandim va derazani sindirib qo'ydim."],["Friend","do'st, o'rtoq",4,"We met at school and became lifelong friends.","Biz maktabda uchrashib qolganmiz va bir umrlik do'stlarga aylanganmiz."],["Friendly","do'stona, xushmuomala",4,"If you are friendly to dogs, they won't hurt you.","Agar siz kuchuklarga xushmuomala bo'lsangiz, ular sizga ozor yetkazmaydi."],["Unfriendly","do'stona bo'lmagan, qo'pol",4,"Lola was very unfriendly. She told me to leave!","Lola juda qo'pol bo'ldi. U mendan ketishimni so'radi!"],["Unkind","qo'pol, qo'rs, qahri qattiq",4,"You were unkind to your aunt. You have to apologise.","Siz xolangizga qo'pol munosabatda bo'ldingiz. Kechirim so'rashingizga to'g'ri keladi."],["Kindness","mehribonchilik, iltifot",4,"She bought me some flowers to thank me for my kindness.","U mehribonchiligim uchun menga tashakkur bildirish maqsadida menga gullar sotib olib berdi."],["Kindly","mehribonlik bilan, iltifot bilan, marhamat bilan",4,"She very kindly invited me to lunch.","U iltifot bilan meni tushlikka taklif qildi."],["Laugh","kulmoq",4,"When I heard her excuse, I just laughed.","Uning bahonasini eshitganimda, men shunchaki kulib yubordim."],["Laughter","kulgi, kulish (ovozi)",4,"I could hear laughter so I knew the children were happy.","Menga uning kulgisi eshitilardi, shundan bildimki bolalar xursand edi."],["Person","shaxs, odam",4,"He's a fascinating person.","U ajoyib odam."],["Personality","shaxsiyat",4,"I think she has a great personality.","O'ylashimcha u ajoyib shaxsiyatga ega."],["Polite","muloyim",4,"Please be polite to our guests.","Iltimos, mehmonlarimizga muloyim bo'ling."],["Impolite","nomuloyim, qo'pol",4,"If you don't speak, people will think you are being impolite.","Agar gapirmasangiz, odamlar sizni qo'pol bo'lyapti deb o'ylaydi."],["Politely","muloyimlik bilan",4,"The receptionist smiled politely.","Qabulxona xodimi muloyimlik bilan jilmaydi."],["Preference","afzallik, ko'proq yoqtirish",4,"We can eat Indian or Chinese food tonight. Do you have a preference?","Bugun oqshomda Hind yoki Xitoy taomi yeyishimiz mumkin. Sizning afzalligingiz bormi? (= Qaysi birini ko'proq yoqtirasiz?)"],["Rely","ishonmoq, suyanmoq, tayanmoq",4,"You can rely on me to keep your secret.","Siringizni saqlashga menga ishonishingiz mumkin."],["Unreliable","ishonib bo'lmaydigan, ishonchsiz",4,"Logan's really unreliable. He says things and then he doesn't do them.","Logen juda ham ishonchsiz. U narsalarni aytadi va keyin ularni qilmaydi."]]},{"n":30,"t":"Weather And Seasons, Nature And Ecology","c":[["Forest","o'rmon",0,"The forest has got thousands of trees.","Bu o'rmonda minglab daraxtlar bor."],["Hill","tepalik, adir",0,"We live in a house on a hill. We can see the town from here.","Biz tepalikdagi uyda yashaymiz. Bu yerdan shaharni ko'ra olamiz."],["Lake","ko'l",0,"There are a lot of fish in the lake.","Bu ko'lda juda ko'p baliq bor."],["Mountain","tog'",0,"Have you ever climbed a high mountain?","Hayotingiz davomida hech bir baland tog'ga chiqqanmisiz?"],["Earthquake","zilzila",0,"There was an earthquake and some houses fell down.","Zilzila bo'ldi va ba'zi uylar qulab tushdi."],["Flooding","suv toshqini",0,"After the rain, we were worried that there would be flooding.","Yomg'irdan so'ng, suv toshqini bo'ladi deb xavotirlandik."],["Hurricane","dovul, to'fon",0,"Hurricanes don't happen very often but they can be dangerous.","To'fonlar tez-tez sodir bo'lmaydi, lekin ular xavfli bo'lishi mumkin."],["Rubbish","axlat",0,"Put your rubbish in the right place. Don't drop litter.","Axlatingizni kerakli joyga qo'ying. Yerga axlat tashlamang."],["Spring","bahor",0,"I like the spring–it's when all the flowers start growing.","Menga bahor yoqadi–u barcha gullar o'sishni boshlaydigan fasl."],["Summer","yoz",0,"The summer is my favourite season because I love sunny days.","Yoz mening sevimli faslim chunki men quyoshli kunlarni yoqtiraman."],["Autumn","kuz",0,"In autumn, the weather starts to get cold.","Kuzda havo sovushni boshlaydi."],["Winter","qish",0,"Winter is cold here. It snows a lot.","Bu yerda qish sovuq bo'ladi. Qor ko'p yog'adi."],["Weather","ob-havo",0,"What's the weather like where you live? Is it very hot?","Siz yashaydigan yerda ob-havo qanday? Juda issiqmi?"],["Blow","(shamol) esmoq, puflamoq, uchirib yubormoq",1,"The wind blew my hat off!","Shamol mening shlyapamni uchirib yubordi!"],["Breathe","nafas olmoq",1,"I like to breathe the fresh air in the forest.","Menga o'rmonda toza havodan nafas olish yoqadi."],["Cut down","kesib tashlamoq",1,"They mustn't cut down all the trees in the forest.","O'rmondagi barcha daraxtlarni kesib tashlamasliklari kerak."],["Pick up","yerdan olmoq",1,"You must pick up your litter. Don't drop it in the street.","Siz axlatingizni yerdan olishingiz kerak. Uni ko'chaga tashlamang."],["Plant","ekmoq",1,"Sometimes pupils from my school go to plant trees.","Ba'zida, maktabimdagi o'quvchilar daraxtlar ekish uchun borishadi."],["Pollute","ifloslantirmoq, zaharlamoq",1,"Cars and buses pollute the air that we breathe.","Mashina va avtobuslar biz nafas oladigan havoni zaharlaydi."],["Rain","yomg'ir yog'moq",1,"When it rains, there is sometimes flooding.","Yomg'ir yog'ganda, ba'zan suv toshqini bo'ladi."],["Recycle","ishlatilgan narsani qayta ishlamoq, masalan: metal mahsulotlarni eritib qaytadan metal mahsulot yasash mumkin",1,"We can recycle glass and plastic bottles. Don't throw them away.","Shisha va plastik baklashkalarni qayta ishlab chiqarishimiz mumkin. Ularni axlatga tashlab yubormang."],["Shine","(quyosh) charaqlamoq",1,"The sun was shining, so we went for a walk.","Quyosh charaqlayotgandi, shuning uchun sayrga chiqdik."],["Snow","qor yog'moq",1,"Does it often snow here in winter?","Bu yerda tez-tez qor yog'ib turadimi qishda?"],["Cloudy","bulutli",2,"I feel unhappy on cloudy days. I love the sun!","Bulutli kunlarda men o'zimni tushkun his qilaman. Men quyoshni yaxshi ko'raman!"],["Cold","sovuq",2,"It's really cold today. Put on your jacket.","Bugun havo juda sovuq. Kurtkangizni kiyib oling."],["Dangerous","xavfli",2,"The pollution in cities is dangerous for your health.","Shaharlardagi ifloslanish sog'lig'ingiz uchun xavflidir."],["Foggy","tumanli, tuman tushgan",2,"It was a foggy day and we couldn't see where we were driving.","Kun tumanli edi va bizga mashinani qayerga haydayotganimiz ko'rinmadi."],["Fresh","toza, musaffo",2,"The air is usually really fresh after the rain.","Yomg'irdan keyin, havo odatda juda toza bo'ladi."],["Sunny","quyoshli, quyosh charaqlab turgan",2,"When it's sunny, we play football or ride our bikes.","Havo quyoshli bo'lganda, biz futbol o'ynaymiz yoki velosiped uchamiz."],["Warm","issiq",2,"It's a warm day today. I think we can swim in the sea.","Bugun kun issiq. O'ylashimcha, dengizda suzsak bo'ladi."],["Windy","shamolli, shamol esayotgan",2,"It's very windy today. I'm happy I don't have to go out!","Bugun havo juda shamolli. Ko'chaga chiqishim shart emasligidan xursandman!"],["Get wet","yomg'irda ivib ketmoq, ho'l bo'lmoq, shalabbo bo'lmoq",3,"Take your umbrella or you'll get wet.","Soyaboningizni olib oling, aks holda shalabbo bo'lasiz."],["In (the) spring/summer/autumn/winter","bahorda/yozda/kuzda/qishda",3,"It's beautiful here in the summer when all the trees are green.","Yoz faslida barcha daraxtlar yam-yashil bo'lgan paytda, bu yer chiroyli bo'ladi."],["In the country(side)","shahar tashqarisida, tabiat qo'ynida",3,"My family lives in the city so when we can, we go for a ride in the country.","Oilam shaharda yashaydi, shuning uchun qachon iloji bo'lsa, tabiat qo'ynida mashinada aylanishga chiqamiz."],["In the sky","osmonda, ko'kda",3,"It was a beautiful spring day. There wasn't a cloud in the sky.","Chiroyli bahor kuni edi. Osmonda bironta ham bulut yo'q edi."],["Keep something clean","biror narsani toza tutmoq",3,"Don't throw litter–we have to keep the countryside clean.","Axlat uloqtirmang–tabiat qo'ynini toza tutishga majburmiz."],["On (the) Earth","sayyorada, Yerda",3,"How many people live on Earth?","Sayyorada nechta odam yashaydi?"],["On a cold/frosty/nasty/rainy/sunny/wet day","sovuq/ayoz/rasvo/yomg'irli/quyoshli/nam kunda",3,"I love going for a walk on a cold, frosty day.","Sovuq, ayozli kunda sayrga chiqish menga yoqadi."],["On the ground","yerda",3,"There's lots of snow on the ground. Let's make a snowman.","Yerda rosa ko'p qor bor. Keling qorbobo yasaymiz."],["Cloud","bulut",4,"We were flying above the clouds.","Biz bulutlardan balandda uchayotgandik."],["Danger","xavf",4,"We weren't in any danger.","Biz hech qanday xavf ostida emasdik."],["Dangerously","xavfli tarzda",4,"Dad never drives dangerously.","Dadam hech qachon xavfli tarzda mashina haydamaydi."],["Fog","tuman",4,"We drove slowly through the fog.","Biz tuman oralab sekinlik bilan haydadik."],["Foggy","tumanli",4,"It was very foggy that morning.","O'sha kuni tongda havo juda tumanli edi."],["Heat","issiqlik",4,"The heat in the factory was unbearable.","Fabrikadagi issiqlik chidab bo'lmas darajada edi."],["Hot","issiq",4,"It's very hot here in the summer.","Yoz faslida bu yer juda issiq bo'ladi."],["Pollute","ifloslantirmoq, zaharlamoq, bulg'amoq",4,"Pesticides can kill wildlife and pollute the atmosphere.","Pestitsidlar (= zararkunandalarga qarshi qo'llaniladigan kimyoviy moddalar) yovvoyi hayotni o'ldirishi va atmosferani ifloslantirishi mumkin."],["Pollution","ifloslanish",4,"The factory is responsible for air pollution.","Fabrika havo ifloslanishi uchun javobgar."],["Polluted","ifloslangan",4,"The air in big cities is often polluted.","Katta shaharlardagi havo odatda ifloslangan bo'ladi."],["Rain","yomg'ir, yog'ingarchilik",4,"There's a lot of rain here in the winter.","Qish faslida bu yerda ko'p yog'ingarchilik bo'ladi."],["Rainy","yomg'irli",4,"I hate rainy days because I have to stay at home.","Menga yomg'irli kunlar yoqmaydi chunki men uyda o'tirishga majbur bo'laman."],["Recycle","qayta ishlamoq",4,"Denmark recycles nearly 85% of its paper.","Denmark davlati qariyb 85% qog'ozini qayta ishlaydi."],["Recycling","qayta ishlash",4,"Recycling is a good way to stop polluting the Earth.","Qayta ishlash sayyorani ifloslantirishni to'xtatishning yaxshi yo'li."],["Recyclable","qayta ishlasa bo'ladigan",4,"Paper, glass and plastic are all recyclable–don't just throw them away.","Qog'oz, shisha va plastmassalarning barini qayta ishlasa bo'ladi–ularni shunchaki axlatga tashlab yubormang."],["Storm","bo'ron",4,"A few minutes later the storm broke.","Bir necha daqiqa o'tgach bo'ron boshlandi."],["Stormy","bo'ronli",4,"The weather has been stormy for a few days. There has been a lot of rain.","Ob-havo bir necha kundan beri bo'ronli bo'lib kelmoqda. Juda ko'p yog'ingarchilik bo'ldi."],["Sun","quyosh",4,"The sun was shining and birds were singing.","Quyosh charaqlayotgandi va qushlar sayrayotgandi."],["Sunny","quyoshli",4,"My mum won't let us stay in on sunny days–she says we have to get some exercise.","Oyim quyoshli kunlarda uyda o'tirishimizga yo'l qo'ymaydilar–ular aytishicha biz ozgina mashq qilishimiz kerak ekan."],["Wind","shamol",4,"The wind is blowing from the south.","Shamol janubdan esmoqda."],["Windy","shamolli",4,"It was very windy and my hat blew off.","Havo juda shamolli edi va mening shlyapam uchib ketdi."]]},{"n":33,"t":"Clothes And Fashion","c":[["Boots","(bir juft) etik",0,"It's snowing, so wear your boots to keep your feet warm.","Qor yog'yapti, shunday ekan oyoqlaringizni issiq saqlash uchun etiklaringizni kiying."],["Cap","kepka, shapka, qalpoq",0,"I wear a cap on my head in the winter.","Qishda men boshimga qalpoq kiyaman."],["Cardigan","kofta, kardigan: to'qilgan odatda yoqasiz kiyim turi",0,"It's a little cold. I'm going to put my cardigan on.","Havo biroz sovuq. Men koftamni kiyib olmoqchiman."],["Coat","palto, kurtka, plash",0,"You'll need your coat–it's going to snow.","Sizga kurtkangiz kerak bo'ladi–qor yog'adi."],["Dress","ayollar ko'ylagi",0,"Lauren is wearing an attractive red dress.","Lo'ren chiroyli qizil ko'ylak kiygan."],["Gloves","(bir juft) qo'lqop",0,"Wear gloves or your hands will get cold.","Qo'lqop kiyib oling, aks holda qo'llaringiz sovuq qotib qoladi."],["Hat","shapka, shlyapa, qalpoq",0,"When it's cold, I wear a hat.","Havo sovuq bo'lganda, men qalpoq kiyaman."],["Jacket","kurtka, pidjak",0,"Poppy always wears the same denim jacket.","Po'pi har doim bir xil ko'jenniy kurtka kiyadi."],["Jeans","jinsi shim",0,"I need a new pair of blue jeans. These are very old.","Menga yangi ko'k jinsi shim kerak. Mana bular juda eski."],["Scarf","sharf",0,"Wear a scarf around your neck because it's very cold.","Bo'yningiz atrofiga sharf bog'lab oling chunki havo juda sovuq."],["Shirt","erkaklar ko'ylagi",0,"What do you think of my new shirt? Does it match my jacket?","Mening yangi ko'ylagim haqida nima deb o'ylaysiz? Kurtkamga mos tushganmi?"],["Shoes","(bir juft) oyoq kiyim: tufli, botinka",0,"Ed doesn't wear leather shoes to school. He always wears trainers.","Ed maktabga charm tufli kiymaydi. U har doim krasovka kiyib boradi."],["Skirt","ayollar yubkasi",0,"Madison never wears trousers. She always wears dresses or skirts.","Madisn hech qachon shim kiymaydi. U doimo ko'ylak yoki yubka kiyadi."],["Socks","(bir juft) paypoq",0,"Hugh's feet are always cold, so he wears his socks to bed.","Hyuning oyoqlari har doim sovuq qotadi, shuning uchun u yotoqda paypoqlarini kiyib yotadi."],["Suit","kostyum shim",0,"This jacket matches my trousers, so it looks like one suit.","Mana bu pidjak shimimga mos tusharkan, shuning uchun u xuddi bitta kostyum shimdek ko'rinadi."],["Sweatshirt","sviter, tolstovka, fufayka",0,"I wear T-shirts but when it's cold, I put a sweatshirt on top.","Men futbolka kiyaman, lekin havo sovuq bo'lganda, uning ustidan sviter kiyib olaman."],["Top","tananing tepa qismiga kiyiladigan kiyim",0,"Gracie wore a green skirt with a matching top.","Greysi koftasiga mos tushadigan yashil yubka kiyib olgandi."],["Trainers","(bir juft) krossovka",0,"I need new trainers so I can play tennis at the weekend.","Dam olish kunida tennis o'ynay olishim uchun menga yangi krasovkalar kerak."],["Trousers","shim",0,"Hannah wears jeans or trousers every day. She doesn't like skirts.","Hana har kuni jinsi shim yoki oddiy shim kiyadi. Unga yubkalar yoqmaydi."],["T-shirt","futbolka",0,"When we do PE at school, we wear white shorts and a T-shirt.","Maktabda jismoniy tarbiya qilganimizda, biz oq sho'rtik va futbolka kiyamiz."],["Belt","kamar, remen",0,"I like to wear a belt with my trousers.","Men shimim bilan kamar taqishni yoqtiraman."],["Fashion","moda, urf",0,"Bright trainers are in fashion this summer.","Yorqin rangdagi krasovkalar bu yozda urfda."],["(Hand)bag","ayollar sumkasi",0,"My mum puts her phone and her money in her handbag.","Oyim telefoni va pulini sumkasiga soladi."],["Hood","kapyushonka",0,"This jacket has a hood. It will keep your head warm.","Bu kurtkaning kapyushonkasi bor. U boshingizni issiq tutadi."],["Pocket","cho'ntak",0,"I always keep my phone in my shirt pocket.","Men har doim telefonimni ko'ylagimning cho'ntagida saqlayman."],["Sleeve","kiyim yengi",0,"In the winter, I wear clothes with long sleeves to keep my arms warm.","Qishda, men qo'llarimni issiq tutish uchun uzun yengli kiyimlar kiyaman."],["(Sun)glasses","(quyoshdan himoya qiluvchi) ko'zoynak",0,"Lucy wears sunglasses on sunny days.","Lusi quyoshli kunlarda ko'zoynak taqadi."],["Watch","qo'l soati",0,"He looked at his watch and saw he was late.","U qo'l soatiga qaradi va kech qolganini ko'rdi."],["Dress up","maxsus kiyimlarni kiymoq, chiroyli kiyimlarni kiymoq",1,"The children sometimes dress up in funny clothes and have a party.","Bolalar ba'zan kulgili kiyimlar kiyib olishadi va bazm qilishadi."],["Fasten","mahkamlamoq, taqmoq: kamarni, zamogni",1,"This jacket is really small–I can't fasten it.","Bu kurtka juda kichik–zamogini taqolmayapman."],["Fit","o'lchami mos tushmoq",1,"This shirt is too big. It doesn't fit me.","Bu ko'ylak haddan tashqari katta. U menga mos emas."],["Grow out of","shunchalik katta bo'lib ketishki ma'lum bir kiyim sizga sig'may qoladi, ma'lum bir kiyim kiyish uchun kichkina bo'lib qolmoq",1,"I grew out of my favourite jacket and I need to buy a new one.","Men sevimli kurtkamni kiyish uchun haddan tashqari katta bo'lib ketdim va men yangisini sotib olishim kerak."],["Match","biror bir kiyim boshqa bir kiyimga mos tushmoq",1,"Luca bought a blue shirt to match his blue trousers.","Luka ko'k shimiga mos tushishi uchun bir ko'k ko'ylak sotib oldi."],["Put on","kiyib olmoq, biror kiyimni ustiga tashlab olmoq",1,"When it's cold, I put on a sweatshirt.","Havo sovuq bo'lganda, men sviter kiyib olaman."],["Suit","yarashmoq",1,"That colour really suits you–it matches your eyes.","Bu rang sizga juda yarashadi–u ko'zlaringizning rangiga mos tushadi."],["Take off","yechmoq",1,"When I take off my clothes, I put them on the armchair.","Kiyimlarimni yechganimda, ularni kreslo ustiga qo'yaman."],["Tie","(oyoq kiyim ipini) bog'lamoq",1,"My little brother is three, so he can't tie his shoes.","Mening ukam uch yoshda, shuning uchun u oyoq kiyimining ipini bog'lay olmaydi."],["Try on","kiyib ko'rmoq (kiyim yarashganmi yoki yo'q, mos tushganmi yoki yo'qligini ko'rish uchun)",1,"I tried the shirt on in the shop, so I know it fits.","Men do'konda ko'ylakni kiyib ko'rdim, shunday ekan bilamanki, uning o'lchami menga mos tushadi."],["Comfortable","qulay",2,"I like these trainers. They're really comfortable for kicking a football.","Bu krasovka menga yoqdi. U koptok tepish uchun juda qulay."],["Fashionable","urfdagi",2,"Fyona bought a fashionable new top to wear to the party.","Fiona bazmga kiyish uchun urfdagi yangi kofta sotib oldi."],["Loose","keng",2,"I prefer clothes that are loose. They feel more comfortable.","Men keng kiyimlarni afzal ko'raman. Ular qulayroq."],["Cotton","paxtadan tikilgan",2,"I like cotton shirts–they're comfortable to wear.","Menga paxtadan tikilgan ko'ylaklar yoqadi– ular kiyish uchun qulay."],["Denim","denimdan tikilgan, jinsi materialli",2,"I like your new denim skirt!","Sizni yangi jinsi materialli yubkangiz menga yoqdi!"],["Leather","teri, charm, ruscha: ko'jenniy material",2,"Li wears a leather jacket and trousers when she rides her motorbike.","Li mototsiklini minganida charm kurtka va shim kiyadi."],["Silk","ipak mato, shoyidan tikilgan",2,"Ella bought a silk dress to wear to her sister's party.","Ela singlisining bazmiga kiyish uchun shoyidan tikilgan ko'ylak sotib oldi."],["Woollen","jundan to'qilgan",2,"I like my woollen sweater–it's very warm.","Jundan to'qilgan sviterim menga yoqadi–u issiqqina."],["Old-fashioned","eskicha, urfdan qolgan",2,"My clothes are a little old-fashioned but I don't care.","Mening kiyimlarim biroz urfdan qolgan, lekin menga farqi yo'q."],["Checked","katak-katakli",2,"Max was wearing a black and white checked shirt.","Maks oq-qora katakli ko'ylak kiyib olgandi."],["Plain","oddiy, ortiqcha rasm yoki chiziqlarsiz",2,"I wanted a plain shirt, not a striped or checked one.","Men oddiygina ko'ylak xohlagandim, chiziq-chiziqli yoki katak-kataklisini emas."],["Spotted","nuqta-nuqtali",2,"I love that spotted dress! Shall I buy it for you?","Bu nuqta-nuqtali ko'ylak menga yoqdi! Sizga sotib olib beraymi?"],["Striped","yo'l-yo'lli, oq-qora chiziqli",2,"Some people say that striped shirts make you look slim.","Ba'zi odamlarning aytishicha, yo'l-yo'l ko'ylaklar odamni xushbichim qilib ko'rsatadi."],["Tight","tor, qisib turadigan",2,"These trousers are really tight. I can't put them on!","Bu shim juda tor. Men uni kiya olmayapman."],["Be in/out of fashion","urfda bo'lmoq/urfdan chiqqan",3,"These jeans are in fashion this year.","Bu jinsi shim bu yili urfda. That colour is out of fashion now. – Bu rang hozir urfdan chiqqan."],["Get dressed","kiyinmoq",3,"I can get dressed in two minutes when I'm late for school.","Maktabga kech qolayotganimda, men ikki daqiqada kiyina olaman."],["Look good on someone","biror kim kiysa yaxshi ko'rinmoq, biror kimga yarashmoq",3,"That shirt looks good on you–where did you buy it?","Bu ko'ylak sizga yarashibdi–qayerdan sotib oldingiz uni?"],["Look smart","bejirim ko'rinmoq, bashang ko'rinmoq, elegant ko'rinmoq",3,"You look smart in those clothes. You could wear them for a party.","Bu kiyimlarda bejirim ko'rinar ekansiz. Ularni bazmga kiyib borsangiz bo'larkan."],["The latest style","eng so'nggi urf = hozirgi paytdagi urf",3,"I'm not interested in the latest style. I like old-fashioned clothes.","Men hozirgi urfga qiziqmadim. Urfdan chiqqan kiyimlar menga yoqadi."],["The right size","to'g'ri o'lcham, kerakli o'lcham, mos o'lcham",3,"I like these trousers but they're not the right size for me.","Menga mana bu shim yoqdi, lekin u menga mos o'lchamda emas ekan."],["Too big/small for someone","biror kim uchun haddan tashqari katta/kichik",3,"I've grown out of these dresses and they're too small for me now.","Men bu ko'ylaklarni kiyish uchun haddan tashqari katta bo'lib ketdim va ular hozir men uchun haddan tashqari kichik. These shoes are too big for me. – Bu oyoq kiyimlar men uchun haddan tashqari katta."],["Wear something on top of/under something","biror bir kiyimning ustidan/ostidan boshqa bir kiyim ham kiyib olmoq",3,"I usually wear a sweatshirt on top my T-shirt.","Men odatda futbolkamning ustidan sviter kiyib olaman. He always wore a blue waistcoat under his blue suit. – U doim ko'k kostyumining ostidan ko'k nimcha (= jiletka) kiyib olardi."],["Colour","rang",4,"What's your favourite colour?","Sizning sevimli rangingiz qaysi?"],["Colourful","rang-barang",4,"That's a very colourful top you're wearing.","Siz kiyib olgan kofta juda rang-barang ekan."],["Comfort","qulaylik",4,"Learn a new language in the comfort of your own home.","O'z uyingizning qulayligini tark etmagan holda (= onlayn) yangi til o'rganing."],["Uncomfortable","noqulay",4,"This chair is uncomfortable–can I sit there?","Bu stul noqulay ekan–anavi yerda o'tirsam maylimi?"],["Unfashionable","urfdan chiqqan",4,"I don't care if my clothes are unfashionable. I'm not interested in fashion.","Kiyimlar urfdan chiqqanligining menga farqi yo'q. Men modaga qiziqmayman."],["Long","uzun",4,"It was the world's longest bridge.","U dunyodadagi eng uzun ko'prik edi."],["Length","uzunlik",4,"We need to know the length of the table before we buy it. It may be too big for the kitchen.","Biz stol sotib olishimizdan avval, uning uzunligini bilishimiz kerak. U oshxonamiz uchun haddan tashqari katta bo'lishi mumkin."],["Real","haqiqiy, chin",4,"She never had any real friends at school.","Uning maktabda hech qachon chin do'stlari bo'lmagan."],["Really","juda",4,"You're a great cook. That food was really good!","Siz zo'r oshpaz ekansiz. Bu ovqat juda yaxshi ekan!"],["Style","moda, fason, stil",4,"Short skirts are back in style.","Kalta yubkalar yana fasonda (= urfga qaytdi)."],["Stylish","didli, zamonaviy",4,"You're looking very stylish today. Are those new clothes?","Bugun juda zamonaviy ko'rinasiz. Bular yangi kiyimlarmi?"],["Trend","urf, ommalashuv",4,"Linen is on trend again this summer.","Gazlama bu yozda yana urfda."],["Trendy","urf bo'lgan, ommalashgan, mashhur",4,"We went to a trendy café. It was a very fashionable place.","Biz ommalashgan (= hozirgi paytda ko'pchilik borayotgan) kafega bordik. U yer juda zamonaviy joy ekan."],["Warm","issiq",4,"Tomorrow will be warm and sunny.","Ertangi kun issiq va quyoshli bo'ladi."],["Warmth","iliqlik",4,"It was winter and I didn't want to get up and leave the warmth of my comfortable bed.","Qish fasli edi va men turishni va mening qulaygina yotog'imning iliqligini tark etishni xohlamadim."],["Wide","keng",4,"How wide is the river?","Daryo qanchalik keng?"],["Width","kenglik, en",4,"Can you tell me the length and the width of this carpet?","Menga mana bu gilamning uzunligi hamda enini aytib yubora olasizmi?"]]},{"n":36,"t":"Jobs And Professions","c":[["Boss","boshliq, xo'jayin",0,"My mum gets on very well with her boss at work.","Oyim ishdagi boshlig'i bilan yaxshi munosabatda."],["Business","biznes; yumush, ish",0,"I'd like to study and have my own business one day.","Men o'qishni va bir kun kelib o'z biznesimga ega bo'lishni xohlayman. We have some unfinished business to discuss. – Bizning muhokama qilishimiz kerak bo'lgan tugallanmagan ishimiz bor."],["Company","kompaniya",0,"My mum works for a travel company in the city centre.","Oyim shahar markazidagi sayohat kompaniyasida (= sayohat agentligida) ishlaydi."],["Factory","fabrika, zavod",0,"He works in a car factory.","U mashina zavodida ishlaydi."],["Dentist","tish shifokori",0,"I went to the dentist to check my teeth.","Men tishlarimni tekshirtirish uchun tish shifokoriga bordim."],["Designer","dizayner",0,"Designers work on many things. If you're creative, you will do well.","Dizaynerlar ko'p narsalar ustida ishlaydi. Agar yaratuvchan bo'lsangiz, ishni yaxshi bajarasiz."],["Doctor","shifokor",0,"Being a doctor is good–you get a lot of money and you help people.","Shifokor bo'lish yaxshi– ko'p pul olasiz va odamlarga yordam berasiz."],["Engineer","muhandis",0,"I want to be an engineer. Then I will design a new car.","Men muhandis bo'lishni xohlayman. Keyin esa yangi mashina dizaynlashtiraman."],["Hairdresser","sartarosh: ayollarniki ham, erkaklarniki ham",0,"A hairdresser cuts and styles people's hair.","Sartarosh odamlarning sochini kesadi va shakl beradi."],["Journalist","jurnalist",0,"A journalist writes things for newspapers or websites.","Jurnalist gazeta va vebsaytlar uchun narsalar yozadi."],["Lawyer","huquqshunos, advokat",0,"You need to know the law very well if you want to be a lawyer.","Agar huquqshunos bo'lishni xohlasangiz, qonunni juda yaxshi bilishingiz kerak bo'ladi."],["Nurse","hamshira",0,"My aunt is a nurse. She works with doctors in the hospital in town.","Mening xolam hamshira. U shahardagi shifoxonada shifokorlar bilan birga ishlaydi."],["Police officer","politsiya ofitseri",0,"You need to be fit and healthy to be a police officer. It's a hard job.","Politsiya ofitseri bo'lish uchun siz baquvvat va sog'lom bo'lishingiz kerak. U mushkul ish."],["Receptionist","qabulxona xodimi, sekretar",0,"My sister works as a receptionist in an office.","Singlim bir ofisda sekretar bo'lib ishlaydi."],["(Shop) assistant","sotuvchi",0,"I work in a department store as a part-time shop assistant.","Men bir univermagda yarim stavkali sotuvchi bo'lib ishlayman (= bir kunda 4 soat)."],["Teacher","o'qituvchi",0,"A teacher usually has to work after school too.","O'qituvchi odatda maktabdan keyin ham ishlashga majbur bo'ladi (= maktab darslari tugaganidan keyin)."],["Tour guide","gid, yo'l boshlovchi",0,"I work as a tour guide in Saint Petersburg.","Men Sent Pitersburgda (= tarixda Leningrad bo'lgan) gid bo'lib ishlayman."],["Waiter/Waitress","ofitsiant/ofitsiantka",0,"My elder brother has a part-time job as a waiter in our local café.","Mening akamning mahalliy kafeda ofitsiant sifatida yarim stavkali ishi bor."],["Manager","ish boshqaruvchi",0,"I'd like to speak to the manager.","Men ish boshqaruvchi bilan gaplashishni xohlayman."],["Office","ofis",0,"I want to work outdoors. I think it'll be boring if I work in an office.","Men ochiq havoda ishlashni xohlayman. Menimcha, agar men ofisda ishlasam, bu zerikarli bo'ladi."],["Staff","ishchi xodimlar",0,"We've got a big staff at my company–100 workers.","Bizning kompaniyada katta raqamdagi ishchi xodimlar bor–100 nafar ishchi."],["Work","ish",0,"It's important to have work but you need free time too.","Ishli bo'lish muhim, lekin bo'sh vaqt ham bo'lishi zarur."],["Apply for","(ishga) hujjat topshirmoq",1,"My dad is a teacher and he's going to apply for a job at my school.","Mening dadam o'qituvchi va u mening maktabimdagi ish uchun hujjat topshirmoqchi."],["Become","kelajakda... bo'lmoq",1,"I think I want to become a dentist when I finish studying.","O'ylashimcha, men o'qishni tamomlaganimda, tish shifokori bo'lishni xohlayman."],["Deal with","bilan shug'ullanmoq, bilan ish yuritmoq",1,"A police officer has to deal with difficult problems daily.","Politsiya ofitseri har kuni murakkab muammolar bilan ish yuritishiga to'g'ri keladi."],["Design","dizaynlashtirmoq, loyihalashtirmoq",1,"I want to design computer games when I finish school.","Men maktabni tamomlaganimda, kompyuter o'yinlari dizaynlashtirishni xohlayman."],["Earn","pul ishlab topmoq",1,"Do you know how much money your dad earns from his job?","Dadangiz ishidan qancha pul ishlab topishini bilasizmi?"],["Help","yordam bermoq",1,"I'm looking for a job where I can help animals–I may become a vet.","Men hayvonlarga yordam bera olishim mumkin bo'ladigan ish izlayapman–kelajakda hayvonlar shifokori bo'lishim mumkin."],["Pay","pul to'lamoq",1,"My parents pay the bills every month.","Ota-onam har oyda iste'mol to'lovlarini (= suv, svet, gaz, axlat uchun) to'lashadi."],["Serve","xizmat ko'rsatmoq, (ovqat, ichimlik) tortmoq",1,"I work as a waiter at weekends. My job is to serve food and drinks.","Men dam olish kunlarida ofitsiant bo'lib ishlayman. Mening ishim yegulik va ichimliklar tortish."],["Teach","o'qitmoq, o'rgatmoq",1,"I think I want to teach English one day.","Menimcha men bir kun kelib ingliz tilini o'rgatishni xohlayman."],["Treat","davolamoq",1,"The doctor treated my dad for a bad cold.","Shifokor dadamni kuchli shamollash uchun davoladi."],["Clever","aqlli, zukko",2,"You have to be clever and work hard to pass all your exams.","Hamma imtihonlardan muvaffaqiyatli o'tish uchun, siz aqlli bo'lishingiz va qattiq ishlashingiz kerak."],["Creative","yaratuvchan, o'zgacha fikrlaydigan, yangi g'oyalarga boy",2,"Designers need to be creative–you have to have good ideas.","Dizaynerlar yaratuvchan bo'lishi kerak–yaxshi g'oyalarga ega bo'lishingiz kerak."],["Freelance","mustaqil, bir necha joyga xizmat ko'rsatuvchi",2,"If you are a freelance designer, you can work for different companies.","Agar siz mustaqil dizayner bo'lsangiz, siz turli kompaniyalarga ishlashingiz mumkin."],["Full-time","to'liq smenada ertalabdan kechgacha ishlovchi, to'liq stavkali",2,"A full-time job is usually about 40 hours a week.","To'liq stavkali ish odatda haftasiga 40 soat bo'ladi."],["Part-time","yarim smenada ishlovchi, yarim stavkali (misol uchun maktab yoki universitet darslaridan keyin)",2,"A part-time job may be 10 or 20 hours a week.","Yarim stavkali ish haftasiga 10 yoki 20 soat bo'lishi mumkin."],["Responsible","mas'uliyatli",2,"You must be responsible if you want to work with children.","Agar bolalar bilan ishlashni istasangiz, siz mas'uliyatli bo'lishingiz kerak."],["Useful","foydali",2,"A good computer is very useful.","Yaxshi kompyuter juda foydali bo'ladi."],["Well-paid","yaxshi haq to'lanadigan",2,"A doctor has a well-paid job. They earn a lot of money.","Shifokor yaxshi haq to'lanadigan ishga ega bo'ladi. Ular ko'p pul topishadi."],["Full-time","ertalabdan kechgacha, to'liq stavkada",2,"My mum works full-time so we help with the housework.","Oyim to'liq stavkada ishlaydilar, shuning uchun biz uy ishlari bilan yordam beramiz."],["Part-time","yarim stavkada",2,"I'm a student so I work part-time to earn money.","Men talabaman, shunday ekan men pul topish uchun yarim stavkada ishlayman."],["Be in charge of","ning nazoratiga javobgar, mas'ul",3,"The manager is in charge of this office. Do you want to speak to him?","Ish boshqaruvchi bu ofisning nazoratiga javobgar. U bilan gaplashishni xohlaysizmi?"],["Find/Get/Have a job","ish topmoq/ish olmoq/ishi bo'lmoq",3,"When I leave school, I'm going to find a job.","Maktabni tark etganimda (= maktabni yakunlaganimda), men ish topmoqchiman."],["Run a business/company/shop/etc","biznesni/kompaniyani/do'konni/va hokazolarni yuritmoq, boshqarmoq",3,"My dad works hard–he runs a business and he is always at the office!","Dadam qattiq ishlaydi–u biznes yuritadi va har doim ofisda!"],["Wear a uniform","maxsus ish kiyimi/maktab formasi kiymoq",3,"Do pupils have to wear a uniform at your school?","O'quvchilar maktabingizda maktab formasi kiyishlari shartmi?"],["Work as a doctor/teacher/etc","shifokor/o'qituvchi/va hokazo bo'lib ishlamoq",3,"My uncle works as a teacher at a school in Leeds.","Mening tog'am Lidzdagi maktabda o'qituvchi bo'lib ishlaydi."],["Work for a company","biror kompaniyada ishlamoq",3,"When you work for a company, you have to follow their rules.","Biror kompaniyada ishlaganingizda, ularning qoidalariga amal qilishingiz shart."],["Work hard","qattiq ishlamoq, tirishib ishlamoq",3,"If you work hard at this job, they'll give you more money.","Agar bu ishda tirishib ishlasangiz, ko'proq pul berishadi."],["Work in a factory/office/plant/etc","fabrika/ofis/zavod/ va hokazoda ishlamoq",3,"Roman works in a factory near Rostov-on-Don.","Roman Rostov-on-Don yaqinidagi fabrikada ishlaydi."],["Assist","yordam bermoq",4,"Your job will be to assist the production manager.","Sizning ishingiz ishlab chiqarish boshqaruvchisiga yordam berish bo'ladi."],["Assistant","yordamchi",4,"Mum works as an assistant to the manager.","Oyim ish boshqaruvchi yordamchisi bo'lib ishlaydilar."],["Bossy","xo'jayinlik qilib buyruq berishni yoqtiradigan",4,"She's really bossy–she always tells us to do things!","U xo'jayinchilik qilishni juda yoqtiradi–u har doim bizga nima qilishni aytadi!"],["Busy","band",4,"The principal is a very busy woman.","Direktor juda ham band ayol."],["Business","biznes",4,"I want to have my own business.","Men o'z shaxsiy biznesimga ega bo'lishni xohlayman."],["Businessman","biznesmen",4,"Sam is a businessman. He runs his own company.","Sem biznesmen. U o'z shaxsiy kompaniyasini yuritadi."],["Businesswoman","tadbirkor ayol",4,"She's a successful businesswoman.","U muvaffaqiyatli tadbirkor."],["Design","dizaynlashtirmoq",4,"He designed and built his own house.","U o'z uyini o'zi dizaynlashtirgan va qurgan."],["Design","dizayn",4,"I like the design of this phone. It's attractive.","Bu telefonning dizayni menga yoqdi. U chiroyli ekan."],["Law","qonun",4,"In Sweden it is against the law to hit a child.","Shvetsiyada bolani urish qonunga zid."],["Manage","boshqarmoq",4,"I think that Forestry Tasmania manages the forest.","Menimcha, bu o'rmonni Tasmania O'rmon Xo'jaligi boshqaradi."],["Reception","qabulxona",4,"I've left the keys at reception.","Men kalitlarni qabulxonada qoldirdim."],["Work","ishlamoq",4,"A lot of mothers choose to work part-time.","Ko'plab onalar yarim stavkada ishlashni tanlashadi."],["Worker","ishchi",4,"My dad is an office manager. There are 15 workers working for him.","Dadam ofis menejeri. 15 nafar ishchi uning qo'l ostida ishlaydi."]]},{"n":39,"t":"Famous People And Places","c":[["Actor/Actress","aktyor/aktrisa",0,"The actors and actresses in that film were very good, weren't they?","Bu filmdagi aktyor va aktrisalar juda yaxshi edi, shunday emasmi?"],["Artist","rassom",0,"Kandinsky was a brilliant artist who painted amazing pictures.","Kardinski ajoyib rasmlar chizgan ajoyib rassom bo'lgan."],["Explorer","tadqiqotchi, yangi joylarni kashf qiluvchi",0,"I want to be an explorer and discover new places.","Men tadqiqotchi bo'lishni hamda yangi yerlarni kashf etishni xohlayman."],["Inventor","ixtirochi",0,"Alexander Graham Bell was the inventor of the telephone, wasn't he?","Aleksandr Greym Bel telefon ixtirochisi bo'lgan, shunday emasmi?"],["King","qirol",0,"Who was the King of England in 1066?","1066-yilda Angliya qiroli kim bo'lgan?"],["Politician","siyosatchi, davlat arbobi",0,"Politicians usually help rule a country.","Davlat arboblari odatda mamlakatni boshqarishga yordam beradi."],["Queen","qirolicha",0,"Queen Victoria ruled Britain from 1837 to 1901.","Qirolicha Viktoriya 1837-yildan 1901-yilgacha Britaniyani boshqargan."],["Singer","qo'shiqchi",0,"She wants to be a singer in a rap band.","U rep guruhida qo'shiqchi bo'lishni xohlaydi."],["Sportsman/Sportswoman","sportchi (erkak/ayol)",0,"Can you earn a lot of money as a sportsman?","Sportchi bo'lib ko'p pul topa olasizmi?"],["Writer","yozuvchi",0,"I want to be a writer. I want to write stories like Turgenev.","Men yozuvchi bo'lishni xohlayman. Turgenevga o'xshab hikoyalar yozishni istayman."],["Building","bino",0,"There are lots of famous buildings in London.","Londonda ko'plab mashhur binolar bor."],["Castle","qal'a",0,"There are lots of old castles in Europe.","Yevropada ko'plab qadimiy qal'alar bor."],["Cathedral","bosh cherkov, ibodatxona",0,"A cathedral is a very big church.","Ibodatxona bir katta cherkovdir."],["Museum","muzey",0,"I love trips to the museum because History is my favourite subject.","Men muzeyga sayohatlarni yoqtiraman chunki Tarix mening sevimli fanim."],["Palace","saroy",0,"We heard a story about a king who lived in a very big palace.","Biz bir juda katta saroyda yashagan qirol to'g'risida hikoya eshitdik."],["Statue","haykal, yodgorlik",0,"One day, if you're famous, they'll build a statue of you!","Bir kun kelib, agar mashhur bo'lib ketsangiz, sizning haykalingizni yasashadi!"],["Tower","minora",0,"Some old castles have towers that you can climb up.","Ba'zi qadimiy qal'alarning tirmashib chiqish mumkin bo'lgan minoralari bor."],["Prize","sovrin",0,"Did you win a prize for coming first in the race?","Poygada birinchi kelganingiz uchun sovrin yutdingizmi?"],["Star","yulduz",0,"I want to become a singer but not a star. I don't want to be famous.","Men yulduz emas, qo'shiqchi bo'lishni xohlayman. Mashhur bo'lishni istamayman."],["Tourist attraction","diqqatga sazovor joy, sayyohlar ko'p tashrif buyuradigan joy",0,"Red Square is the biggest tourist attraction in Moscow.","Qizil Maydon Moskvadagi sayyohlar eng ko'p tashrif buyuradigan joy."],["World record","jahon rekordi, dunyo rekordi",0,"Which athlete holds the world record for the 100-metre race?","Qaysi sportchi 100 metrga yugurish bo'yicha jahon rekordini o'rnatgan?"],["Build","qurmoq, barpo etmoq",1,"I wonder if it's hard to build a house.","Qiziq, uy qurish qiyinmikin?"],["Create","yaratmoq",1,"I'd like to create a new kind of mobile phone.","Men uyali telefonning yangi turini yaratishni xohlayman."],["Discover","kashf qilmoq, birinchi marotaba topmoq",1,"Do you know who discovered America?","Amerikani kim kashf qilganini bilasizmi?"],["Go in","ichkariga kirmoq",1,"I didn't want to go in the classroom and do my exams!","Men sinfga kirib, imtihonlarimni topshirishni xohlamadim!"],["Perform","sahna asari ko'rsatmoq, tomosha qo'ymoq, spektakl qo'ymoq; (rol) ijro etmoq",1,"Do you think it is difficult to perform in front of people in a theatre?","Nima deb o'ylaysiz, teatrda odamlar qarshisida rol ijro etish qiyinmi?"],["Play","o'ynamoq",1,"What part are you going to play in the performance?","Spektaklda qaysi rolni o'ynamoqchisiz?"],["Rule","(mamlakatni) boshqarmoq",1,"The queen ruled the country for many years.","Qirolicha mamlakatni ko'p yillar mobaynida boshqardi."],["Visit","tashrif buyurmoq",1,"Which country are we going to visit next year?","Kelasi yilda qaysi davlatga tashrif buyuramiz?"],["Walk around","aylanmoq (piyoda)",1,"It's nice to walk around the city at night.","Tunda shahar aylanish ajoyib."],["Wonder at","biror narsadan hayratda qolmoq",1,"I always wonder at the beauty of Saint Basil's Cathedral.","Men har doim Sent Bazl Cherkovining chiroyidan hayratda qolaman."],["Brilliant","ajoyib, zo'r",2,"Come and see this new computer game. It's brilliant!","Kelib mana bu kompyuter o'yini bir ko'ring. Bu juda ajoyib!"],["Fantastic","ajoyib, zo'r, hayratlanarli",2,"The trip to the museum was fantastic. I really enjoyed it.","Muzeyga sayohat ajoyib bo'ldi. Men mazza qildim."],["Fast","tezkor",2,"Are you a fast runner?","Siz tezkor yuguruvchimisiz?"],["Great","zo'r, ajoyib",2,"My grandfather tells some great stories about the past.","Mening bobom o'tmish haqida ajoyib hikoyalar aytib beradilar."],["Rich","boy, puldor",2,"I want to become rich and buy lots of cars and houses!","Men boy bo'lishni va juda ko'p mashinalar va uylar sotib olishni xohlayman!"],["Successful","muvaffaqiyatli",2,"A successful student will get a certificate.","Muvaffaqiyatli o'quvchi sertifikat oladi."],["Talented","iqtidorli, qobilyatli",2,"There are a lot of very talented actors and actresses in the theatre.","Teatrda ko'plab juda iqtidorli aktyor va aktrisalar bor."],["Well-known","mashhur, taniqli",2,"Buckingham Palace is a well-known building in London.","Bakinem Saroyi Londondagi taniqli bino."],["Anywhere","biror yerga/da",2,"Are you going to go anywhere nice after the end of term?","Semester yakunidan so'ng biror yaxshi joyga bormoqchimisiz?"],["Fast","tez",2,"My dad's car is OK but it doesn't go very fast.","Dadamning mashinasi yaxshi, lekin u juda tez yurmaydi."],["All around the world","butun dunyodan, butun dunyo bo'ylab",3,"I've travelled all around the world and this is my favourite place.","Men butun dunyo bo'ylab sayohat qilganman va bu mening eng sevimli yerim."],["Be a big fan of","ning ashaddiy muhlisi bo'lmoq",3,"I'm a big fan of Selena Gomez. I think she's a great singer.","Men Selena Gomezning ashaddiy muhlisiman. Menimcha, u ajoyib qo'shiqchi."],["Be born in (a place/year)","(ma'lum bir joyda/yilda) tug'ilgan bo'lmoq",3,"I was born in Tomsk in 2004.","Men 2004-yilda Tomsk shahrida tug'ilganman."],["Be famous for something","biror narsasi uchun mashhur bo'lmoq",3,"Daniel Craig is famous for acting in James Bond films.","Danyel Kreyg Jeyms Bond filmlarida rol o'ynagani uchun mashhur."],["Be located in","da joylashgan bo'lmoq",3,"Novosibirsk is located in Siberia.","Novosibirsk Siberiyada joylashgan."],["Be the first person to do something","biror ishni qilgan eng birinchi inson bo'lmoq",3,"Who was the first person to travel into space?","Koinotga sayohat qilgan eng birinchi inson kim bo'lgan?"],["Hold the record for","biror narsa bo'yicha rekord natijani o'rnatgan bo'lmoq",3,"Who holds the record for the most goals in a football match?","Futbol o'yinida eng ko'p go'l urganlik bo'yicha rekordni kim o'rnatgan?"],["Hope to meet/see/visit","uchratib qolishni/ko'rishib qolishni/tashrif buyurishni umid qilmoq",3,"I hope to visit my cousins in Cyprus next year.","Men kelasi yili Kiprdagi amakivachchalarimnikiga tashrif buyurishga umid qilaman."],["Collect","to'plamoq, yig'moq",4,"She collects dolls.","U qo'g'irchoqlar yig'adi."],["Collector","kolleksioner: biror narsa to'plovchi odam",4,"Dad loves old cars. He's a collector.","Dadamga eski mashinalar yoqadi. U kolleksioner."],["Collection","kolleksiya, to'plam",4,"I have a big collection of songs–over 5,000.","Menda katta qo'shiqlar to'plami bor–5,000 dan ziyod."],["Describe","tasvirlamoq",4,"Can you describe him to me?","Uni menga tasvirlab bera olasizmi?"],["Description","tasvir, tavsif",4,"Can you give me a description of the man you saw? What was he wearing?","Siz ko'rgan erkakning tasvirini menga bera olasizmi? U nima kiyib olgandi?"],["Discovery","kashfiyot, topilma, topib olinish",4,"The discovery of the old castle was very exciting.","Qadimiy qal'aning topib olingani juda ajoyib bo'ldi."],["Discoverer","kashfiyotchi",4,"Who was the discoverer of America?","Amerikaning kashfiyotchisi kim bo'lgan?"],["Explore","tadqiq etmoq: biror joy haqida ko'proq o'rganish uchun u yerni aylanmoq",4,"The best way to explore the countryside is on foot.","Shahar tashqarisini tadqiq etishning eng yaxshi usuli piyoda aylanish."],["Explorer","tadqiqotchi",4,"We learned about explorers in our History lesson.","Biz tarix darsimizda tadqiqotchilar haqida o'rgandik."],["Exploration","tadqiqot; aylanish, ko'rib chiqish, o'rganish",4,"Exploration of a new city is always exciting.","Yangi shaharni o'rganish har doim ham ajoyib."],["Fame","mashhurlik, shon-shuhrat",4,"She found fame on the stage.","U sahnada shon-shuhrat topdi (= mashhurlikka erishdi)."],["Famous","mashhur, taniqli",4,"Alexander Pushkin was a famous Russian writer.","Aleksandr Pushkin taniqli Rus yozuvchisi bo'lgan."],["Invent","ixtiro qilmoq",4,"Thomas Edison invented the light bulb.","Tomas Edisn lampochkani ixtiro qilgan."],["Invention","ixtiro",4,"The computer is a great invention.","Kompyuter ajoyib ixtiro."],["Perform","namoyish ko'rsatmoq, spektakl qo'ymoq",4,"The play was first performed in 2007.","Ushbu spektakl ilk marotaba 2007-yilda qo'yilgan."],["Performer","ijrochi, ishtirokchi",4,"The performers made us laugh.","Ijrochilar bizni kuldirishdi."],["Performance","ijro, spektakl, sahna ko'rinishi, tomosha",4,"We went to the theatre to watch a performance.","Biz spektakl ko'rish uchun teatrga bordik."],["Success","muvaffaqiyat",4,"Confidence is the key to success.","Ishonch muvaffaqiyat kaliti."],["Talent","iqtidor, talant, qobilyat",4,"You have a natural talent for storytelling.","Sizning hikoya aytishga tabiiy iqtidoringiz bor."],["Talented","iqtidorli, talantli, qobilyatli",4,"Morgan is a talented violin player. He may become famous one day.","Mo'gen iqtidorli skripkachi. U bir kun kelib mashhur bo'lishi mumkin."],["Tour","aylanmoq, sayohat qilmoq",4,"He's toured across Europe, the UK and North America.","U Yevropa, Birlashgan Qirollik hamda Shimoliy Amerika bo'ylab sayohat qilgan."],["Tour","sayohat, biror joyni aylanib chiqish",4,"Did you go on a bus tour in Ottawa?","Ottavani avtobusda aylanib chiqdingizmi?"],["Tourist","sayyoh, turist",4,"Millions of tourists visit Paris every year to see the sights.","Millionlab sayyohlar har yili diqqatga sazovor joylarni ko'rish uchun Parijga tashrif buyuradi."]]},{"n":42,"t":"Communication And Technology","c":[["App","mobil ilova, dastur",0,"You can get apps for your phone that help you learn English.","Telefoningizga ingliz tilini o'rganishingizga yordam beruvchi mobil ilovalarni olishingiz mumkin."],["Keyboard","klaviatura",0,"Most laptops have a compact keyboard.","Ko'pchilik noutbuklarning ixchamgina klaviaturasi bo'ladi."],["Mouse","kompyuter sichqonchasi",0,"I use a mouse when I work on the computer.","Men kompyuterda ishlaganimda, sichqonchadan foydalanaman."],["Printer","printer",0,"I haven't got a printer, so I have to read things on the screen.","Mening printerim yo'q, shuning uchun men narsalarni kompyuter ekranida o'qishga majburman."],["Screen","ekran",0,"Some people buy computers with really big screens.","Ba'zi odamlar juda katta ekranli kompyuterlar sotib oladi."],["Software","dasturiy ta'minot: kompyuter programmalari",0,"A piece of software is usually a program that you download.","Dasturiy ta'minot odatda siz yuklab oladigan bir programma."],["Touchpad","tachped: sichqoncha kursorini boshqaruvchi kompyuterga birlashtirilgan sezuvchan panel",0,"There's a touchpad on this laptop but you can use a mouse if you like.","Bu noutbukda tachped bor, lekin agar istasangiz, sichqonchadan foydalanishingiz mumkin."],["Email address","elektron pochta manzili",0,"Give me your email address so I can send you the homework.","Sizga uyga vazifani jo'nata olishim uchun, menga elektron pochta manzilingizni bering."],["Laptop","noutbuk",0,"Would you prefer to have a laptop or a tablet?","Noutbukka ega bo'lishni afzal ko'rgan bo'larmidingiz yoki planshetgami?"],["(Smart)phone","smartfon",0,"A smartphone is more than just a phone. It's like a little computer in your pocket.","Smartfon shunchaki telefon emas. U go'yoki cho'ntagingizdagi bir kichik kompyuter."],["Tablet","planshet",0,"I like to read e-books on my tablet.","Men planshetimda elektron kitoblar o'qishni yoqtiraman."],["Social media/network","ijtimoiy tarmoq",0,"Most young people chat to each other on social media.","Ko'pchilik yoshlar bir-biri bilan ijtimoiy tarmoqlarda suhbatlashadi."],["Text (message)","yozuvli xabar, SMS",0,"Sending a text message is often cheaper than making a phone call.","Odatda SMS jo'natish qo'ng'iroq qilishdan arzonroq."],["The internet","internet",0,"I love the internet and I go online every evening.","Menga internet yoqadi va men har oqshomda internetga kiraman."],["Website","vebsayt",0,"Some of the websites I see online are really interesting.","Men internetda ko'radigan ba'zi vebsaytlar juda qiziqarli."],["Browse","internetda o'tirmoq, bir saytdan ikkinchisiga o'tib yurmoq",1,"I'm not doing anything special. I'm just browsing on the internet.","Men hech qanday maxsus ish qilmayapman. Men shunchaki internetda o'tiribman."],["Call","qo'ng'iroq qilmoq",1,"I'll call you after school. We'll speak then.","Men maktabdan so'ng sizga qo'ng'iroq qilaman. O'shanda gaplashamiz."],["Click","bosmoq",1,"Click on this link if you want to see my website.","Agar mening vebsaytimni ko'rishni istasangiz, mana bu link ustiga bosing."],["Download/Upload","internetdan yuklab olmoq/internetga yuklamoq, joylamoq",1,"I upload photos to social media so my friends can see them.","Do'stlarim ko'ra olishi uchun, rasmlarni ijtimoiy tarmoqqa joylayman. You can download the app for free. – Ilovani bepul yuklab olishingiz mumkin."],["Install","o'rnatmoq (ilovani kompyuter yoki telefonga)",1,"You need to install a program on your computer to download music.","Musiqa yuklab olish uchun, kompyuteringizga ilova o'rnatishingiz zarur."],["Log in(to)/Log on(to)/Log out","tizim yoki vebsaytga kirmoq/kirmoq/dan chiqmoq (kompyuterda ishlaganda)",1,"When you log into this website, they ask for your telephone number.","Bu vebsaytga kirganingizda, sizning telefon raqamingizni so'rashadi. You need a password to log on. – Tizimga kirish uchun sizga parol kerak bo'ladi. Make sure you log out of your account on public computers. – Jamoat kompyuterlarida shaxsiy akkauntingizdan chiqib ketishga ishonch hosil qiling."],["Post","internetga joylamoq, qo'ymoq",1,"Don't post things that are not nice when you're using social media.","Ijtimoiy tarmoqdan foydalanayotganingizda, yaxshi bo'lmagan narsalarni internetga joylamang."],["Send","jo'natmoq, yubormoq",1,"Shall I send you an email when I get to Rome?","Rimga yetib borganimda sizga email yuboraymi?"],["Subscribe to","ga a'zo bo'lmoq, obuna bo'lmoq",1,"Which blog do you subscribe to?","Qaysi blogga obuna bo'lgansiz?"],["Text","xabar yozmoq",1,"Don't forget to text me when you arrive in Madrid.","Madridga yetib borganingizda menga xabar yozishni unutmang."],["Chatty","ko'pgap, vaysaqi",2,"I'm not a very chatty person. I don't like talking.","Men juda ham ko'pgap odam emasman. Gapirishni yoqtirmayman."],["Digital","raqamli",2,"I want a ditigal camera because they take great photos.","Menga raqamli kamera (= fotoapparat) kerak chunki ular rasmlarni zo'r oladi."],["Downloadable","internetdan yuklab olsa bo'ladigan",2,"This website has got downloadable exercises that you can do at home.","Bu vebsaytda uyda bajarishingiz mumkin bo'lgan yuklab olsa bo'ladigan mashqlar bor."],["Online","onlayn, internetda",2,"Online shopping is popular because you can order what you want from your home computer.","Internetda xarid qilish mashhur chunki siz uydagi kompyuteringizdan xohlagan narsangizga buyurtma berishingiz mumkin."],["Shy","uyatchan, tortinchoq",2,"I'm very shy, so I don't like to see pictures of me on the screen.","Men juda uyatchanman, shuning uchun ekranda rasmlarimni ko'rishni yoqtirmayman."],["Smart","aqlli, kompyuterlashtirilgan",2,"I want to buy a smart TV–they're as good as a computer.","Men aqlli televizor sotib olishni xohlayman–ular xuddi kompyuterdek yaxshi."],["At once","bir pastda, o'sha zahotiyoq",2,"We met at a party and became good friends at once.","Biz bazmda uchrashganmiz va o'sha zahotiyoq yaxshi do'stlarga aylanganmiz."],["Immediately","darrov, bir zumda, birdaniga, bir pastda",2,"I looked for the answer online and I found it immediately.","Men internetdan javobni qidirdim va uni bir zumda topdim."],["Answer the/your phone","qo'ng'iroqqa javob bermoq",3,"I was calling you–why didn't you answer your phone?","Men sizga qo'ng'iroq qilayotgandim– nima uchun qo'ng'iroqqa javob bermadingiz?"],["Click on a link","URL linkning ustiga bosmoq",3,"Be careful on the internet because when you click on a link, it may not be what it says it is.","Internetda ehtiyotkor bo'ling chunki biror link ustiga bosganingizda, u aytilgan narsa bo'lmasligi mumkin."],["Comment on a post/video/etc","postga/videoga/va hokazoga nisbatan fikr bildirmoq",3,"It's OK to comment on a post online but you must always be polite.","Internetda biror postga nisbatan fikr bildirsangiz bo'ladi, lekin doimo xushmuomala bo'lishingiz kerak."],["Follow someone on Instagram/VK/etc","Instagramda/VKontaktda/boshqa ijtimoiy tarmoqlarda biror kimni kuzatmoq",3,"All my friends follow me on Instagram.","Barcha do'stlarim meni Instagramda kuzatib boradi."],["Go online","internetga kirmoq, onlayn bo'lmoq",3,"I've got a computer in my room but I don't go online every day.","Xonamda kompyuter bor, lekin men har kuni ham internetga kirmayman."],["Have a conversation/chat with someone","biror kim bilan suhbatlashmoq, gaplashmoq",3,"I had a chat with Jasmine yesterday. She told me to say hello to you.","Kecha men Jasmin bilan suhbatlashdim. U sizga salom aytib qo'yishimni aytdi."],["Surf the internet","internetdan qidirmoq, internetda o'tirmoq",3,"I was surfing the internet to find ideas for my homework.","Men uyga vazifam uchun g'oyalar topish maqsadida internetda o'tirgandim."],["Take/Post a selfie","selfi olmoq/internetga joylamoq",3,"When I was in Rome, I took a selfie and posted it on Instagram for my friends to see.","Rimda bo'lgan paytimda, men selfi oldim va do'stlarim ko'rishi uchun uni Instagramga joyladim."],["Attach","biriktirmoq, qo'shib jo'natmoq",4,"I am attaching the image as a PDF file.","Rasmni PDF fayl shaklida qo'shib jo'natyapman."],["Attachment","biriktirib jo'natilgan narsa",4,"I sent the picture as an email attachment.","Rasmni emailga biriktirib jo'natdim."],["Blog","blog",4,"You can read about my trip in my blog.","Sayohatim to'g'risida blogimda o'qishingiz mumkin."],["Blog","blog yuritmoq",4,"Finley blogs about his life in Ireland.","Finley Irlandiyadagi hayoti to'g'risida blog yuritadi."],["Blogger","blogger",4,"I'm not a blogger but I read what other people write in their blogs.","Men blogger emasman, lekin boshqa odamlar o'z bloglarida yozgan narsalarni o'qiyman."],["Blogging","blog yuritish, bloggerlik qilish",4,"Blogging is a great way to write what you think.","Blog yuritish - bu o'z fikringizni yozishning ajoyib usuli."],["Chat","suhbat",4,"We had a nice chat over a cup of tea.","Biz bir finjon choy ustida ajoyib suhbat qurdik."],["Chat","suhbatlashmoq, gaplashmoq",4,"The girls are chatting online now.","Qizlar hozir internetda suhbatlashishyapti."],["Communicate","aloqa qilmoq",4,"We usually communicate by letter.","Biz odatda xat orqali aloqa qilamiz."],["Communication","aloqa",4,"Online communication is fast–you can send a message very quickly.","Onlayn aloqa tezkor–siz juda tezlik bilan xabar jo'natishingiz mumkin."],["Download","internetdan yuklab olmoq",4,"You can download unlimited e-books for free.","Cheksiz elektron kitoblarni bepul yuklab olishingiz mumkin."],["Follow","kuzatmoq",4,"I don't follow many celebrities on Twitter any more.","Men bundan buyon Twitterda ko'p mashhurlarni kuzatib bormayman."],["Follower","kuzatuvchi",4,"I have 500 followers who read my posts on Instagram.","Mening Instagramda postlarimni o'qib boradigan 500 nafar kuzatuvchim bor."],["Listen","tinglamoq",4,"I was listening to the radio.","Men radio tinglayotgan edim."],["Listener","tinglovchi",4,"Good afternoon, listeners! Welcome to the programme!","Assalom aleykum, tinglovchilar! Ko'rsatuvga xush kelibsiz!"],["Speak","gapirmoq",4,"You must speak loudly and clearly on the stage.","Sahnada baland ovozda va tiniq gapirishingiz kerak."],["Speech","nutq, ma'ruza",4,"Are you worried about giving your speech tomorrow?","Ertaga beradigan nutqingiz haqida havotirdamisiz?"],["Speaker","spiker: gapiruvchi odam",4,"The manager was the first speaker at the meeting.","Ish boshqaruvchi uchrashuvdagi birinchi spiker bo'ldi."],["Subscribe","a'zo bo'lmoq, obuna bo'lmoq",4,"To hear the full interview, subscribe to the free National Geographic News podcast.","To'liq intervyuni eshitish uchun, bepul National Geographic News podkastiga obuna bo'ling."],["Subscription","obuna",4,"Do you have to have a subscription to that music website to listen to music?","Musiqa tinglash uchun, o'sha vebsaytga obuna bo'lgan bo'lishingiz shartmi?"],["Subscriber","obunachi",4,"There are over 5,000 subscribers to this website.","Bu vebsaytning 5,000 dan ziyod obunachisi bor."]]}]};
